COLLDATA("tadabburar","ar",[[142,"§الأنعام\nwords\nقُبُلًامُوَاجَهَةً.\nغُرُورًاخِدَاعًا.\nوَلِتَصغَىلِتَمِيلَ.\nوَلِيَقتَرِفُوالِيَكتَسِبُوا.\nيَخرُصُونَيَظُنُّونَ وَيَكذِبُونَ.\ndeeds\nأكثر من دعاء الله سبحانه أن يهديك، ويثبتك على الدين؛ فإن الهداية بيده وحده سبحانه.\nاقرأ كتابًا عن مخططات الصهيونية العالمية؛ للتعرف على طريقة تفكير أعداء الأنبياء من شياطين الإنس.\nتعرف على أحكام الذبائح الجائزة والمحرمة من خلال قراءة كتاب في ذلك أو استماع درس.\nguid\nمن أساليب أهلِ الباطل تحسين القول وزخرفته، مع أنه في داخله لا يتضمن إلا الفساد.\nالقلوب الفارغة من الإيمان بالله أكثر القلوب إصغاء لأهل الشهوات والشبهات.\nالكثرة ليست دليلًا على الحق.\nrefl\nوَكَذَٰلِكَ جَعَلۡنَا لِكُلِّ نَبِيٍّ عَدُوّٗا شَيَٰطِينَ ٱلۡإِنسِ وَٱلۡجِنِّ يُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورٗاۚ\nقال قتادة ومجاهد والحسن: \"إن من الإنس شياطين، كما أن من الجن شياطين\"... وقال مالك بن دينار: \"إن شياطين الإنس أشد عليَّ من شياطين الجن؛ وذلك أني إذا تعوذت بالله ذهب عني شيطان الجن، وشيطان الإنس يجيئني فيجرني إلى المعاصي عيانًا\". البغوي:٢/٥٦.\nهل في الإنس شياطين كالجن؟ وأيهم أشد خطرًا؟\nيُوحِي بَعۡضُهُمۡ إِلَىٰ بَعۡضٖ زُخۡرُفَ ٱلۡقَوۡلِ غُرُورٗاۚ\nيزين بعضهم لبعض الأمر الذي يدعون إليه من الباطل، ويزخرفون له العبارات؛ حتى يجعلوه في أحسن صورة؛ ليغتر به السفهاء، وينقاد له الأغبياء الذين لا يفهمون الحقائق، ولا يفقهون المعاني، بل تعجبهم الألفاظ المزخرفة، والعبارات المموهة، فيعتقدون الحق باطلًا، والباطل حقًا. السعدي:٢٦٩-٢٧٠.\nلماذا يهتم أهل الباطل بزخرفة أقوالهم وتجميلها؟\nوَلِتَصۡغَىٰٓ إِلَيۡهِ أَفۡـِٔدَةُ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ وَلِيَرۡضَوۡهُ\nأخبر أن كلام أعداء الرسل تصغى إليه أفئدة الذين لا يؤمنون بالآخرة؛ فعُلم أن مخالفة الرسل وترك الإيمان بالآخرة متلازمان؛ فمن لم يؤمن بالآخرة أصغى إلى زخرف أعدائهم فخالف الرسل، كما هو موجود في أصناف الكفار والمنافقين في هذه الأمة وغيرها. ابن تيمية:٣/٨٩-٩٠.\nمخالفة الرسل وترك الإيمان بالآخرة متلازمان، بين ذلك.\nوَتَمَّتۡ كَلِمَتُ رَبِّكَ صِدۡقٗا وَعَدۡلٗاۚ لَّا مُبَدِّلَ لِكَلِمَٰتِهِۦۚ وَهُوَ ٱلسَّمِيعُ ٱلۡعَلِيمُ ١١٥\n(وتمت كلمة ربك صدقًا وعدلًا): فالله تعالى بعث الرسل بالعلم والعدل؛ فكل من كان أتم علمًا وعدلًا كان أقرب إلى ما جاءت به الرسل. ابن تيمية:٣/٩٣.\nما الأمور التي تحدد مقدار قربك مما جاء به الرسل -عليهم السلام-؟\nوَإِن تُطِعۡ أَكۡثَرَ مَن فِي ٱلۡأَرۡضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِۚ إِن يَتَّبِعُونَ إِلَّا ٱلظَّنَّ وَإِنۡ هُمۡ إِلَّا يَخۡرُصُونَ ١١٦\nوسبب هذه الأكثرية: أن الحق والهدى يحتاج إلى عقول سليمة، ونفوس فاضلة، وتأمُّلٍ في الصالح والضار، وتقديم الحق على الهوى، والرشد على الشهوة، ومحبة الخير للناس؛ وهذه صفات إذا اختل واحد منها تطرق الضلال إلى النفس بمقدار ما انثلم من هذه الصفات. ابن عاشور:٨/٢٥.\nما سبب كثرة أهل الضلال في الأرض؟\nوَإِن تُطِعۡ أَكۡثَرَ مَن فِي ٱلۡأَرۡضِ يُضِلُّوكَ عَن سَبِيلِ ٱللَّهِۚ١١٦\nدلت هذه الآية على أنه لا يستدل على الحق بكثرة أهله، ولا يدل قلة السالكين لأمر من الأمور أن يكون غير حق، بل الواقع بخلاف ذلك؛ فإن أهل الحق هم الأقلون عددًا، الأعظمون عند الله قدرًا وأجرًا. السعدي:٢٧٠.\nانتشر اليوم بين الناس الإيمان بالأكثرية، وتغليبها على الأقلية، فما حكم الشرع في هذا؟\nفَكُلُواْ مِمَّا ذُكِرَ ٱسۡمُ ٱللَّهِ عَلَيۡهِ إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤۡمِنِينَ ١١٨\n﴿إِن كُنتُم بِـَٔايَٰتِهِۦ مُؤۡمِنِينَ﴾ أي: إن كنتم بأحكامه وأوامره آخذين؛ فإن الإيمان بها يتضمن ويقتضي الأخذ بها والانقياد لها. ابن عطية:٢/٣٣٨.\nلماذا ختم الأمر بالأكل مما ذكر اسم الله عليه بذكر الإيمان؟"],[143,"§الأنعام\nwords\nصَغَارٌذُلٌّ، وَهَوَانٌ.\ndeeds\nسم الله تعالى عند الأكل من الطيبات.\nحاسب نفسك اليوم عن باطن الآثام التي لا يطلع عليها إلا الله تعالى.\nأرسل رسالة تحذر فيها من الأكل مما لم يذكر اسم الله عليه.\nguid\nوجوب ترك الإثم؛ ظاهرًا كان أو باطنًا، وسواء كان من أعمال القلوب أو أعمال الجوارح.\nاحرص على إطابة مطعمك بأن تأكل المذبوحات التي ذُكِرَ عليها اسم الله، وتترك ما عدا ذلك.\nالشرك موت وظلمة، والإيمان حياة ونور.\nrefl\nوَقَدۡ فَصَّلَ لَكُم مَّا حَرَّمَ عَلَيۡكُمۡ\nودلت الآية الكريمة على أن الأصل في الأشياء والأطعمة الإباحة، وأنه إذا لم يرد الشرعُ بتحريم شيء منها فإنه باقٍ على الإباحة، فما سكت الله عنه فهو حلال؛ لأن الحرام قد فَصَّلَه الله، فما لم يفصله الله فليس بحرام. السعدي:٢٧١.\nكيف يستدل بالآية على القاعدة الشرعية: (الأصل في الأشياء الإباحة)؟\nوَإِنَّ كَثِيرٗا لَّيُضِلُّونَ بِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ ١١٩\nفكل من اتبع ذوقًا أو وجدًا بغير هدى من الله، سواء كان ذلك عن حب أو بغض؛ فليس لأحد أن يتبع ما يحبه فيأمر به ويتخذه دينًا، وينهى عما يبغضه ويذمه ويتخذ ذلك دينًا، إلا بهدى من الله؛ وهو شريعة الله التي جعل عليها رسوله. ومن اتبع ما يهواه حبًّا وبغضًا بغير الشريعة فقد اتبع هواه بغير هدى من الله. ابن تيمية:٣/٩٦.\nبيّن خطورة اتباع الأهواء بغير علم من الله تعالى.\nوَإِنَّ كَثِيرٗا لَّيُضِلُّونَ بِأَهۡوَآئِهِم بِغَيۡرِ عِلۡمٍۚ إِنَّ رَبَّكَ هُوَ أَعۡلَمُ بِٱلۡمُعۡتَدِينَ ١١٩\nثم بيّن -عز وجل- في ضلالهم أنه على أقبح الوجوه، وأنه بالهوى لا بالنظر والتأمل، و﴿بِغَيۡرِ عِلۡمٍۚ﴾ معناه: في غير نظر. ابن عطية:٢/٣٣٩.\nما أشد أنواع الضلال؟\nوَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ إِنَّ ٱلَّذِينَ يَكۡسِبُونَ ٱلۡإِثۡمَ سَيُجۡزَوۡنَ بِمَا كَانُواْ يَقۡتَرِفُونَ ١٢٠\nولا يتم للعبد ترك المعاصي الظاهرة والباطنة إلا بعد معرفتها والبحث عنها، فيكون البحث عنها ومعرفة معاصي القلب والبدن والعلم بذلك واجبًا متعينًا على المكلف. وكثير من الناس تخفى عليه كثير من المعاصي، خصوصًا معاصي القلب؛ كالكبر والعجب والرياء ونحو ذلك، حتى إنه يكون به كثير منها، وهو لا يحس به ولا يشعر، وهذا من الإعراض عن العلم وعدم البصيرة. السعدي:٢٧١.\nما أول ما على المرء فعله لاجتناب الآثام والمعاصي الظاهرة والباطنة؟\nوَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ إِنَّ ٱلَّذِينَ يَكۡسِبُونَ ٱلۡإِثۡمَ سَيُجۡزَوۡنَ بِمَا كَانُواْ يَقۡتَرِفُونَ ١٢٠\n﴿وَذَرُواْ ظَٰهِرَ ٱلۡإِثۡمِ وَبَاطِنَهُۥٓۚ﴾: لفظ يعم أنواع المعاصي؛ لأن جميعها إما باطن وإما ظاهر، وقيل: الظاهر: الأعمال، والباطن: الاعتقاد. ابن جزي:١/٢٨٤.\nجمعت هذه الآية بين الإيجاز والعموم، وضح ذلك.\nوَإِنَّ ٱلشَّيَٰطِينَ لَيُوحُونَ إِلَىٰٓ أَوۡلِيَآئِهِمۡ لِيُجَٰدِلُوكُمۡۖ\nودلَّت هذه الآية الكريمة على أن ما يقع في القلوب من الإلهامات والكشوف، التي يكثر وقوعها عند الصوفية ونحوهم، لا تدل بمجردها على أنها حق، ولا تصدق حتى تُعرض على كتاب الله وسنة رسوله؛ فإن شهدا لها بالقبول قُبلت، وإن ناقضتهما رُدت، وإن لم يعلم شيء من ذلك تُوقِّف فيها ولم تُصدق ولم تُكذب؛ لأن الوحي والإلهام يكون من الرحمن ويكون من الشيطان، فلا بد من التمييز بينهما والفرقان، وبعدم التفريق بين الأمرين حصل من الغلط والضلال ما لا يحصيه إلا الله. السعدي:٢٧١.\nكيف ترد بهذه الآية على من يؤمن بالإلهامات والكشوفات من غير عرضٍ على الكتاب والسنة؟\nوَكَذَٰلِكَ جَعَلۡنَا فِي كُلِّ قَرۡيَةٍ أَكَٰبِرَ مُجۡرِمِيهَا لِيَمۡكُرُواْ فِيهَاۖ وَمَا يَمۡكُرُونَ إِلَّا بِأَنفُسِهِمۡ وَمَا يَشۡعُرُونَ ١٢٣\n﴿وَكَذَٰلِكَ جَعَلۡنَا فِي كُلِّ قَرۡيَةٍ أَكَٰبِرَ﴾ أي: كما جعلنا في مكة أكابرها ليمكروا فيها، جعلنا في كل قرية، وإنَّما ذكر الأكابر لأن غيرهم تبع لهم. ابن جزي:١/٢٨٤.\nما وجه الاقتصار في الآية على الأكابر دون غيرهم؟"],[144,"§الأنعام\nwords\nحَرَجًاشَدِيدَ الضِّيقِ.\nيَصَّعَّدُ فِي السَّمَاءِيَصعَدُ فِي طَبَقَاتِ الجَوِّ.\nالرِّجسَالعَذَابَ.\nدَارُ السَّلاَمِدَارُ السَّلاَمَةِ وَالأَمَانِ وَهِيَ الجَنَّةُ.\nاستَمتَعَانتَفَعَ.\ndeeds\nادع الله تعالى أن يشرح صدرك للحق حيث كان.\nاذكر نعمة الله تعالى عليك بالهداية، حيث شرح صدرك للإسلام، ولو شاء لم تكن كذلك.\nاستعذ بالله تعالى من شر الجن.\nguid\nالهداية بيد الله -سبحانه وتعالى-؛ فاسألها مِن مالكها.\nالقلوب الكافرة يلقى فيها كل ما لا خير فيه من الشهوات والشبهات، وهي مرتع للشيطان.\nأكثر من الأعمال الصالحة؛ فإنها سبب لولاية الله.\nrefl\nفَمَن يُرِدِ ٱللَّهُ أَن يَهۡدِيَهُۥ يَشۡرَحۡ صَدۡرَهُۥ لِلۡإِسۡلَٰمِۖ\nيقول تعالى مبينًا لعباده علامة سعادة العبد وهدايته... إن من انشرح صدره للإسلام -أي: اتسع وانفسح- فاستنار بنور الإيمان، وحيي بضوء اليقين، فاطمأنت بذلك نفسه، وأحب الخير، وطوعت له نفسُه فعلَه، متلذِّذًا به غير مستثقل؛ فإن هذا علامة على أن الله قد هداه، ومَنَّ عليه بالتوفيق، وسلوك أقوم الطريق. السعدي:٢٧٢.\nما علامة الهداية التي يحسها المرء من نفسه؟\nوَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ\nأي: كأنما يحاول الصعود إلى السماء، وذلك غير ممكن، فكذلك يصعب عليه الإيمان. ابن جزي:١/٢٨٥.\nما وجه الشبه بين الضالّ ومن يريد الصعود إلى السماء؟\nوَمَن يُرِدۡ أَن يُضِلَّهُۥ يَجۡعَلۡ صَدۡرَهُۥ ضَيِّقًا حَرَجٗا كَأَنَّمَا يَصَّعَّدُ فِي ٱلسَّمَآءِۚ\nشبه الله الكافر في نفوره عن الإيمان وثقله عليه بمنزلة من تَكلَّف ما لا يطيقه؛ كما أن صعود السماء لا يُطاق. القرطبي:٩/٢٥.\nتقبُّل الإيمان صعب بل مستحيل على من كُتبت عليه الضلالة، وضح ذلك.\nلَهُمۡ دَارُ ٱلسَّلَٰمِ عِندَ رَبِّهِمۡۖ وَهُوَ وَلِيُّهُم بِمَا كَانُواْ يَعۡمَلُونَ ١٢٧\nيعني: الجنة، وسميت دار السلام لأن كل من دخلها سلم من البلايا والرزايا. البغوي:٢/٦٣.\nما المقصود بدار السلام؟ ولم سميت بذلك؟\nوَكَذَٰلِكَ نُوَلِّي بَعۡضَ ٱلظَّٰلِمِينَ بَعۡضَۢا بِمَا كَانُواْ يَكۡسِبُونَ ١٢٩\nكذلك من سنتنا أن نولي كل ظالم ظالمًا مثله؛ يؤزه إلى الشر، ويحثه عليه، ويزهده في الخير، وينفره عنه، وذلك من عقوبات الله العظيمة الشنيع أثرها، البليغ خطرها. والذنب ذنب الظالم؛ فهو الذي أدخل الضرر على نفسه، وعلى نفسه جنى، ﴿وَمَا رَبُّكَ بِظَلَّٰمٍ لِّلۡعَبِيدِ﴾. ومن ذلك: أن العباد إذا كثر ظلمهم وفسادهم، ومنعهم الحقوق الواجبة، ولَّى عليهم ظلمة يسومونهم سوء العذاب، ويأخذون منهم بالظلم والجور أضعاف ما منعوا من حقوق الله وحقوق عباده. السعدي:١/٢٧٣.\nبيّن مظهرين من مظاهر تولي الظالمين بعضهم لبعض.\nوَكَذَٰلِكَ نُوَلِّي بَعۡضَ ٱلظَّٰلِمِينَ بَعۡضَۢا بِمَا كَانُواْ يَكۡسِبُونَ ١٢٩\nوهذا تهديد للظالم؛ إن لم يمتنع من ظلمه سلط الله عليه ظالمًا آخر... قال فضيل بن عياض: \"إذا رأيت ظالمًا ينتقم من ظالم؛ فقف وانظر فيه متعجبًا\". القرطبي:٩/٣٠.\nبماذا يُعاقب الله تعالى الظالم في الدنيا؟\nيَٰمَعۡشَرَ ٱلۡجِنِّ وَٱلۡإِنسِ أَلَمۡ يَأۡتِكُمۡ رُسُلٞ مِّنكُمۡ يَقُصُّونَ عَلَيۡكُمۡ ءَايَٰتِي وَيُنذِرُونَكُمۡ لِقَآءَ يَوۡمِكُمۡ هَٰذَاۚ قَالُواْ شَهِدۡنَا عَلَىٰٓ أَنفُسِنَاۖ وَغَرَّتۡهُمُ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَشَهِدُواْ عَلَىٰٓ أَنفُسِهِمۡ أَنَّهُمۡ كَانُواْ كَٰفِرِينَ ١٣٠\nومعناه: قد أتاكم رسل منكم ينبهونكم على خطأ ما كنتم عليه مقيمين بالحجج البالغة، وينذرونكم وعيد الله على مقامكم على ما كنتم عليه مقيمين، فلم تقبلوا ذلك، ولم تتذكروا ولم تعتبروا. الطبري:١٢/١٢٠.\nالتذكير بالمخالفات قبل إيقاع العقوبة منهج القرآن، وضح ذلك من خلال الآية."],[145,"§الأنعام\nwords\nمَكَانَتِكُمطَرِيقَتِكُم.\nعَاقِبَةُ الدَّارِالعَاقِبَةُ، وَالمَآلُ الحَسَنُ.\nذَرَأَخَلَقَ.\nالحَرثِالزُّرُوعِ.\nلِيُردُوهُملِيُهلِكُوهُم.\nوَلِيَلبِسُوالِيَخلِطُوا.\nيَفتَرُونَيَختَلِقُونَهُ مِنَ الكَذِبِ.\ndeeds\nاقرأ كتابًا عن أشراط الساعة الصغرى والكبرى.\nادع الناس لعمل صالح، مع قيامك به؛ فهما أمران متلازمان.\nأرسل رسالة تحذر فيها إخوانك المسلمين من الظلم، مذكرًا أن الظالم لا يفلح في الدنيا ولا في الآخرة.\nguid\nدرجتك عند الله تعالى بحسب عملك الصالح.\nوعد الله لا يتبدل.\nالظالم لا يفلح في الدنيا ولا في الآخرة.\nrefl\nوَلِكُلّٖ دَرَجَٰتٞ مِّمَّا عَمِلُواْۚ\nبحسب أعمالهم؛ لا يجعل قليل الشر منهم ككثيره، ولا التابع كالمتبوع، ولا الرئيس كالمرؤوس، كما أن أهل الثواب والجنة وإن اشتركوا في الربح، والفلاح، ودخول الجنة؛ فإن بينهم من الفرق ما لا يعلمه إلا الله، مع أنهم كلهم قد رضوا بما آتاهم مولاهم. السعدي:٢٧٤.\nما الفائدة العملية من معرفة أن أهل الجنة متفاوتون في الدرجات؟\nوَرَبُّكَ ٱلۡغَنِيُّ ذُو ٱلرَّحۡمَةِۚ\nوإنَّما أمر الله العباد بالأعمال الصالحة، ونهاهم عن الأعمال السيئة رحمةً بهم، وقصدًا لمصالحهم، وإلا فهو الغني بذاته عن جميع مخلوقاته؛ فلا تنفعه طاعة الطائعين، كما لا تضره معصية العاصين. السعدي:٢٧٤.\nلماذا وصف الله نفسه بالغني بعد أن ذكر جزاء المؤمنين والفاجرين؟\nإِن يَشَأۡ يُذۡهِبۡكُمۡ وَيَسۡتَخۡلِفۡ مِنۢ بَعۡدِكُم مَّا يَشَآءُ كَمَآ أَنشَأَكُم مِّن ذُرِّيَّةِ قَوۡمٍ ءَاخَرِينَ ١٣٣\nفإذا عرفتم بأنكم لا بد أن تنتقلوا من هذه الدار كما انتقل غيركم، وترحلون منها وتخلونها لمن بعدكم، كما رحل عنها من قبلكم وخلوها لكم؛ فلِمَ اتخذتموها قرارًا، وتوطنتم بها، ونسيتم أنها دار ممر لا دار مقر؟! وأن أمامكم دارًا هي الدار التي جمعت كل نعيم، وسلمت من كل آفة ونقص؟! وهي الدار التي يسعى إليها الأولون والآخرون. وما أبخس حظ من رضي بالدون! وأدنى همةَ من اختار صفقة المغبون! السعدي:٢٧٤.\nما الذي يفيده العاقل من ذهاب أمم وزوالها، ثم يخلفها غيرها؟\nفَقَالُواْ هَٰذَا لِلَّهِ بِزَعۡمِهِمۡ وَهَٰذَا لِشُرَكَآئِنَاۖ فَمَا كَانَ لِشُرَكَآئِهِمۡ فَلَا يَصِلُ إِلَى ٱللَّهِۖ وَمَا كَانَ لِلَّهِ فَهُوَ يَصِلُ إِلَىٰ شُرَكَآئِهِمۡۗ سَآءَ مَا يَحۡكُمُونَ ١٣٦\nوسمى الشياطين شركاء لأنهم أطاعوهم في معصية الله، فأشركوهم مع الله في وجوب طاعتهم. القرطبي:٩/٣٩.\nلماذا سمى الله تعالى الشياطين شركاء؟\nوَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ\nأضيف الفعل وهو القتل إلى الشركاء وإن لم يتولوا ذلك؛ لأنهم زينوا ذلك، ودعوا إليه؛ فكأنهم فعلوه. القرطبي:٩/٣٩٣.\nهل من زين المنكر، وحث عليه، ودعا له، يعتبر كالفاعل المقارف له؟\nوَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ وَلَوۡ شَآءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ ١٣٧\nكانوا يقتلون أولادهم بالوأد، ويذبحونهم قربانًا إلى الأصنام. وشركاؤهم هنا هم: الشياطين، أو القائمون على الأصنام. (ليُردُوهم) أي: ليهلكوهم، وهو من الرَّدى بمعنى الهلاك. ابن جزي:١/٢٨٧.\nمن خلال هذه الآية بين شيئًا من فضل الله علينا بهذا الدين.\nوَكَذَٰلِكَ زَيَّنَ لِكَثِيرٖ مِّنَ ٱلۡمُشۡرِكِينَ قَتۡلَ أَوۡلَٰدِهِمۡ شُرَكَآؤُهُمۡ لِيُرۡدُوهُمۡ وَلِيَلۡبِسُواْ عَلَيۡهِمۡ دِينَهُمۡۖ وَلَوۡ شَآءَ ٱللَّهُ مَا فَعَلُوهُۖ فَذَرۡهُمۡ وَمَا يَفۡتَرُونَ ١٣٧\nوالشركاء هاهنا: الشياطين، الآمرون بذلك، المزينون له، والحاملون عليه أيضًا من بني آدم الناقلين له عصرًا بعد عصر؛ إذ كلهم مشتركون في قبح هذا الفعل، وتبعاته في الآخرة. ابن عطية:٢/٣٤٩.\nمتى يصير المرء شريكًا للشيطان؟"],[146,"§الأنعام\nwords\nحِجرٌمُحَرَّمَةٌ.\nمَعرُوشَاتٍمُحتَاجَةً إِلَى العَرِيشِ؛ كَالعِنَبِ وَالعَرِيشُ: أَعوَادٌ تُنصَبُ لِيَتَمَدَّدَ عَلَيهَا الشَّجَرُ، وَيَرتَفِعَ عَنِ الأَرضِ.\nوَغَيرَ مَعرُوشَاتٍقَائِمَةً عَلَى سَاقِهَا؛ كَالنَّخلِ.\nحَمُولَةًمَا هُوَ مُهَيَّأٌ لِلحَملِ عَلَيهِ؛ كَالإِبِلِ.\nوَفَرشًامَا هُوَ مُهَيّأٌ لِغَيرِ الحَملِ لِصِغَرِهِ، وَقُربِهِ مِنَ الأَرضِ؛ كَالغَنَمِ.\ndeeds\nسل الله تعالى صلاح الأولاد، وأن يعينك على تربيتهم التربية الصالحة.\nاختر لحظة تشتد فيها حاجة الفقراء، وتصدق فيها بصدقة؛ لعله يتضاعف أجرك.\nاحمد الله تعالى عند الأكل والشرب.\nguid\nالنذور للأولياء والأضرحة هي من عمل المشركين؛ زين ذلك الشيطان لجهال المسلمين.\nتحديد النسل من عمل الجاهلية؛ وهو من سوء الظن بالله سبحانه.\nالإسراف صفة مذمومة يكرهها الله -سبحانه وتعالى-، فلا تكن من المسرفين.\nrefl\nوَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن مَّيۡتَةٗ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ ١٣٩\n﴿إِنَّهُۥ حَكِيمٌ عَلِيمٌ﴾: تعليل للوعد بالجزاء؛ فإن الحكيم العليم بما صدر عنهم لا يكاد يترك جزاءهم الذي هو من مقتضيات الحِكمَة. الألوسي:٨/٣٨٩.\nما الفائدة من ختم الآية بصفتي الحكمة والعلم لله -عز وجل-؟\nوَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن مَّيۡتَةٗ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ ١٣٩\nوفي الآية دليل على أن العالم ينبغي له أن يتعلم قول من خالفه، وإن لم يأخذ به؛ حتى يعرف فساد قوله، ويعلم كيف يرد عليه؛ لأن الله تعالى أعلم النبي -صلى الله عليه وسلم- وأصحابه قول من خالفهم من أهل زمانهم ليعرفوا فساد قولهم. القرطبي:٩/٤٨.\nبيّن الفائدة الجليلة التي يتعلمها طالب العلم من هذه الآية؟\nوَقَالُواْ مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٞ لِّذُكُورِنَا وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ وَإِن يَكُن مَّيۡتَةٗ فَهُمۡ فِيهِ شُرَكَآءُۚ سَيَجۡزِيهِمۡ وَصۡفَهُمۡۚ إِنَّهُۥ حَكِيمٌ عَلِيمٞ ١٣٩\nومن آرائهم السخيفة: أنهم يجعلون بعض الأنعام ويعينونها محرمًا ما في بطنها على الإناث دون الذكور؛ فيقولون: ﴿مَا فِي بُطُونِ هَٰذِهِ ٱلۡأَنۡعَٰمِ خَالِصَةٌ لِّذُكُورِنَا﴾ أي: حلال لهم، لا يشاركهم فيها النساء، ﴿وَمُحَرَّمٌ عَلَىٰٓ أَزۡوَٰجِنَاۖ﴾ أي: نسائنا؛ هذا إذا ولد حيًّا، وإن يكن ما [في] بطنها يولد ميتًا فهم فيه شركاء؛ أي: فهو حلال للذكور والإناث. السعدي:٢٧٦.\nفي الآية مقارنة بين القوانين الوضعية والشريعة الإسلامية، وضح ذلك.\nقَدۡ خَسِرَ ٱلَّذِينَ قَتَلُوٓاْ أَوۡلَٰدَهُمۡ سَفَهَۢا بِغَيۡرِ عِلۡمٖ وَحَرَّمُواْ مَا رَزَقَهُمُ ٱللَّهُ ٱفۡتِرَآءً عَلَى ٱللَّهِۚ قَدۡ ضَلُّواْ وَمَا كَانُواْ مُهۡتَدِينَ ١٤٠\nكثر في القرآن استعارة الخسران لعمل الذين يعملون طلبًا لمرضاة الله وثوابه فيقعون في غضبه وعقابه؛ لأنهم أتعبوا أنفسهم، فحصَّلوا عكس ما تعبوا لأجله. ابن عاشور:٨/١١٣.\nما الخسران الحقيقي الَّذي ورد ذكره في الآية الكريمة؟\nوَءَاتُواْ حَقَّهُۥ يَوۡمَ حَصَادِهِۦۖ\nأمرهم أن يعطوها يوم حصادها، وذلك... لأنه الوقت الذي تتشوف إليه نفوس الفقراء، ويسهل حينئذ إخراجه على أهل الزروع، ويكون الأمر فيها ظاهرًا لمن أخرجها؛ حتى يتميز المخرج ممن لا يخرج. السعدي:٢٧٦.\nلماذا أمر بزكاة الزروع يوم حصادها؟\nوَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ ١٤١\nقال الزهري: المعنى: لا تنفقوا في معصية الله تعالى، ويروى نحوه عن مجاهد؛ فقد أخرج ابن أبي حاتم عنه أنه قال: \"لو كان أبو قبيس ذهبًا، فأنفقه رجل في طاعة الله تعالى لم يكن مسرفًا، ولو أنفق درهمًا في معصية الله تعالى كان مسرفًا\". الألوسي:٨/٣٩٢.\nما الإسراف المنهي عنه في الآية كما فسره علماء السلف الصالح؟\nوَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ ١٤١\nأي: لا تُسرِفُوا فِي الأكلِ؛ لِمَا فيهِ مِن مَضَرَّةِ العقل والبدن؛ كقوله تعالى: ﴿وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ﴾ [الأعراف:٣١]، وفي صحيحِ البخارِي تَعليقًا: «كُلُوا واشربوا والبسوا وتصدّقوا؛ من غَيرِ إِسرافٍ ولا مخيلَة». ابن كثير:٢/١٧٤.\nلماذا نُهينا عن الإسراف في الأكل؟"],[147,"§الأنعام\nwords\nأَزوَاجٍأَصنَافٍ.\nأُهِلَّ لِغَيرِ اللَّهِذُكِرَ عِندَ ذَبحِهِ اسمُ غَيرِ اللهِ.\nكُلَّ ذِي ظُفُرٍكُلَّ مَا لَم يَكُن مَشقُوقَ الأَصَابِعِ؛ كَالإِبِلِ وَالنَّعَامِ.\nالحَوَايَاالأَمعَاءَ.\ndeeds\nاجمع أنواع المحرمات في الآية، واعرف المراد منها.\nاكتب رسالة تبين فيها أن الطعام الحلال أكثر وأعظم بركة من الطعام الحرام، فعلينا الاكتفاء به.\nراجع أنواع الأطعمة التي تأكلها، وابتعد عن المحرم أو ما كان شديد الاشتباه؛ لأن عاقبته سيئة على الدين، والعقل، والبدن.\nguid\nلا أحد أظلمُ ممن يكذب على الله تعالى، فيشرع لعباده ما لم يشرعه الله.\nعلى المفتي الذي يفتي الناس بالحل والحرمة أن يفتي عن علم، وإلا كان داخلًا تحت الوعيد.\nإمهال الله تعالى المجرمين لا يدل على عدم عقوبتهم؛ فإن بأس الله لا يعلم متى يأتي.\nrefl\nأَمۡ كُنتُمۡ شُهَدَآءَ إِذۡ وَصَّىٰكُمُ ٱللَّهُ بِهَٰذَاۚ فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ١٤٤\n﴿أَمۡ كُنتُمۡ شُهَدَآءَ﴾ أي: هل شاهدتم الله قد حرم هذا؟ ولما لزمتهم الحجة أخذوا في الافتراء فقالوا: كذا أمر الله، كذا أمر الله، فقال الله تعالى: ﴿فَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبًا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ﴾؛ بيّن أنهم كذبوا إذ قالوا ما لم يقم عليه دليل. القرطبي:٩/٧٩.\nما الواجب على كل من أراد أن يتكلم في حكم، أو مسألة، أو نازلة؟\nفَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ١٤٤\nبيّن تعالى سوء مقصدهم بالافتراء؛ لأنه لو افترى أحد فرية على الله لغير معنى لكان ظلمًا عظيمًا، فكيف إذا قصد بهما إضلال أمة؟! ابن عطية:٢/٣٥٥.\nافتراء الكذب له دركات، فأيها أسوأ؟\nفَمَنۡ أَظۡلَمُ مِمَّنِ ٱفۡتَرَىٰ عَلَى ٱللَّهِ كَذِبٗا لِّيُضِلَّ ٱلنَّاسَ بِغَيۡرِ عِلۡمٍۚ إِنَّ ٱللَّهَ لَا يَهۡدِي ٱلۡقَوۡمَ ٱلظَّٰلِمِينَ ١٤٤\nمن الظلم أن يقدم أحد على الإفتاء في الدين ما لم يكن قد غلب على ظنه أنه يفتي بالصواب الذي يرضي الله؛ وذلك إن كان مجتهدًا فبالاستناد إلى الدليل الذي يغلب على ظنه مصادفته لمراد الله تعالى، وإن كان مقلدًا فبالاستناد إلى ما يغلب على ظنه أنه مذهب إمامه الذي قلده. ابن عاشور:٨/١٣٥.\nلا يجوز الإقدام على الفتوى بغير علم، بين ذلك.\nأَوۡ دَمٗا مَّسۡفُوحًا\nهو الدم الذي يخرج من الذبيحة عند ذكاتها؛ فإنه الدم الذي يضر احتباسه في البدن، فإذا خرج من البدن زال الضرر بأكل اللحم. السعدي:٢٧٧.\nلماذا أمر الله بسفح هذا الدم عند ذكاة الذبيحة؟\nأَوۡ دَمٗا مَّسۡفُوحًا\nمفهوم هذا اللفظ: أن الدم الذي يبقى في اللحم والعروق بعد الذبح أنه حلال طاهر. السعدي:٢٧٧.\nذكر الله لنا حكم الدم المسفوح، فما حكم الدم الباقي بعد الذبح في الجسد والعروق؟\nوَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا كُلَّ ذِي ظُفُرٖۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمٖۚ ذَٰلِكَ جَزَيۡنَٰهُم بِبَغۡيِهِمۡۖ وَإِنَّا لَصَٰدِقُونَ ١٤٦\nأي: ذلك التحريم عقوبة لهم. (ببغيهم) أي: بظلمهم من: قتلهم الأنبياء، وصدهم عن سبيل الله، وأخذهم الربا، واستحلال أموال الناس بالباطل. البغوي:٢/٧٥.\nللمعصية شؤم على أهلها، بيّن ذلك من خلال الآية.\nوَعَلَى ٱلَّذِينَ هَادُواْ حَرَّمۡنَا كُلَّ ذِي ظُفُرٖۖ وَمِنَ ٱلۡبَقَرِ وَٱلۡغَنَمِ حَرَّمۡنَا عَلَيۡهِمۡ شُحُومَهُمَآ إِلَّا مَا حَمَلَتۡ ظُهُورُهُمَآ أَوِ ٱلۡحَوَايَآ أَوۡ مَا ٱخۡتَلَطَ بِعَظۡمٖۚ ذَٰلِكَ جَزَيۡنَٰهُم بِبَغۡيِهِمۡۖ وَإِنَّا لَصَٰدِقُونَ ١٤٦\n﴿وَعَلَى ٱلَّذِينَ هَادُواْ﴾ أي: اليهود خاصة... (ببغيهم) أي: بسبب ظلمهم وهو قتلهم الأنبياء بغير حق، وأكلهم الربا وقد نهوا عنه، وأكلهم أموال الناس بالباطل، وكانوا كلما أتوا بمعصية عوقبوا بتحريم شيء مما أُحِلَّ لَهُم. الألوسي:٨/٤٠٥.\nأذية الصالحين وقتلهم مؤذنة للعقوبات الربانية، وضح ذلك."],[148,"§الأنعام\nwords\nبَأسُهُعَذَابُهُ.\nتَخرُصُونَتَكذِبُونَ.\nهَلُمَّهَاتُوا.\nيَعدِلُونَيُسَوُّونَ بِهِ غَيرَهُ وَيُشرِكُونَ.\nإِملاَقٍفَقرٍ.\ndeeds\nحدد وسائل إعلام المنافقين، وقاطعها؛ فهم يبثون عبرها كذبهم وخداعهم.\nاعمل اليوم شيئًا من البر عظيمًا تحسن به إلى والديك؛ سواء كانا أحياءً أم أمواتًا؛ فقد وصاك الله تعالى بهما.\nاقرأ معاني ما تضمنته الآية من وصايا وأوامر وصانا الله تعالى بها لتتمكن من امتثال هذه الوصايا.\nguid\nإذا رأيت الظالم يتمادى في غيه فلا تحزن؛ فإن الله تعالى ينزل بأسه بالقوم المجرمين، فإذا نزل بهم فلا يستطيع أحد رده.\nعلى الداعية أن لا يستبعد احتمال تكذيبه من قِبَل بعض المدعوين؛ فلا يكـن ذلك عائقًا أمامه.\nالهداية بيد الله -سبحانه وتعالى-؛ فاطلبها منه.\nrefl\nفَإِن كَذَّبُوكَ فَقُل رَّبُّكُمۡ ذُو رَحۡمَةٖ وَٰسِعَةٖ\nوهذا ترغيب لهم في ابتغاء رحمة الله الواسعة، واتباع رسوله. ابن كثير:٢/١٧٧.\nلماذا ذُكِرَت رحمة الله بعد ذكر تكذيبهم للرسول؟\nسَيَقُولُ ٱلَّذِينَ أَشۡرَكُواْ لَوۡ شَآءَ ٱللَّهُ مَآ أَشۡرَكۡنَا وَلَآ ءَابَآؤُنَا وَلَا حَرَّمۡنَا مِن شَيۡءٖۚ\nفإن المشركين استدلوا بالقدر على نفي الأمر والنهي، والمحبوب والمكروه، والطاعة والمعصية. ومن سلك هذا المسلك فهو في نوع من الكفر البيّن. ابن تيمية:٣/١١٢.\nبيّن في ضوء الآية الكريمة خطورة الاستدلال بالقدر على نفي الأمر والنهي.\nقُلۡ تَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ أَلَّا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗاۖ\nذكر في هذه الآيات المحرمات التي أجمعت عليها جميع الشرائع، ولم تنسخ قط في ملة، وقال ابن عباس: \"هي الكلمات التي أنزل الله على موسى\". ابن جزي:١/٢٩١.\nما الميزة أو الخاصية التي اختُصّت بها هذه الوصايا؟\nقُلۡ تَعَالَوۡاْ أَتۡلُ مَا حَرَّمَ رَبُّكُمۡ عَلَيۡكُمۡۖ أَلَّا تُشۡرِكُواْ بِهِۦ شَيۡـٔٗاۖ وَبِٱلۡوَٰلِدَيۡنِ إِحۡسَٰنٗاۖ\nهذه الآية أمر من الله تعالى لنبيه -عليه الصلاة والسلام- بأن يدعو جميع الخلق إلى سماع تلاوة ما حرم الله، وهكذا يجب على من بعده من العلماء أن يبلغوا الناس، ويبينوا لهم ما حرم الله عليهم مما حل. القرطبي:٩/١٠٦.\nإلى أي شيء دعانا الله تعالى في هذه الآية؟\nوَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُم مِّنۡ إِمۡلَٰقٖ نَّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡۖ\nقال في سورة الإسراء: ﴿وَلَا تَقۡتُلُوٓاْ أَوۡلَٰدَكُمۡ خَشۡيَةَ إِمۡلَٰقٍ﴾ [الإسراء: ٣١] أي: لا تقتلوهم خوفًا من الفقر في الآجل، ولهذا قال هناك: ﴿نَّحۡنُ نَرۡزُقُهُمۡ وَإِيَّاكُمۡ﴾؛ فبدأ برزقهم للاهتمام بهم؛ أي: لا تخافوا من فقركم بسبب رزقهم؛ فهو على الله، وأمَّا هنا فلما كان الفقر حاصلًا؛ قال: ﴿نَّحۡنُ نَرۡزُقُكُمۡ وَإِيَّاهُمۡۖ﴾؛ لأنه الأهم هاهنا. ابن كثير:٢/١٨٠.\nلماذا قدم رزق الآباء على رزق الأبناء في هذه السورة، وقُدِّم رزق الأبناء على رزق الآباء في سورة الإسراء؟\nوَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ\nأي: لا تقربوا الظاهر منها والخفي، أو المتعلق منها بالظاهر، والمتعلق بالقلب والباطن. والنهي عن قربان الفواحش أبلغ من النهي عن مجرد فعلها؛ فإنه يتناول النهي عن مقدماتها ووسائلها الموصلة إليها. السعدي:٢٨٠.\nلماذا نهى عن قربان الفواحش، ولم يكتفِ بالنهي عن الفواحش فقط؟\nوَلَا تَقۡرَبُواْ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَۖ وَلَا تَقۡتُلُواْ ٱلنَّفۡسَ ٱلَّتِي حَرَّمَ ٱللَّهُ إِلَّا بِٱلۡحَقِّۚ\nوهذا مما نص -تبارك وتعالى- على النهي عنه تأكيدًا، وإلا فهو داخل في النهي عن الفواحش ما ظهر منها وما بطن؛ فقد جاء في الصحيحين، عن ابن مسعود -رضي الله عنه- قال: قال رسول الله -صلى الله عليه وسلم-: «لا يحل دم امرئ مسلم يشهد أن لا إله إلا الله وأني رسول الله إلا بإحدى ثلاث: الثيب الزاني، والنفس بالنفس، والتارك لدينه المفارق للجماعة». ابن كثير:٢/١٨٠.\nالنهي عن قتل النفس داخل في النهي عن الفواحش، فلماذا أعاد النهي عنه؟"],[149,"§الأنعام\nwords\nيَبلُغَ أَشُدَّهُيَصِلَ إِلَى سِنِّ البُلُوغِ، وَيَكُونَ رَاشِدًا.\nبِالقِسطِبِالعَدلِ.\nدِرَاسَتِهِمقِرَاءَةِ كُتُبِهِم.\nوَصَدَفَأَعرَضَ.\ndeeds\nاكفل يتيمًا مباشرةً، أو عن طريق مؤسسة موثوق فيها؛ فإن الله تعالى وصّى باليتيم في ماله، فكيف بمن يكفله من عنده.\nانصح بعض الباعة المطففين في المكيال والميزان.\nتعاهد نفسك بقول العدل في كل أمر، ولو على نفسك.\nguid\nالتزام الإسلام والبراءة من غيره من الملل والطرق المنحرفة والمبتدعة هو الطريق المستقيم الموصل إلى الجنة.\nلقد حَذَّر الله من العبث بحقوق اليتامى، ومن أكل أموالهم؛ فابتعد عن ذلك أشد الابتعاد.\nمن كان له عملٌ وتجارةٌ قائمة على الكيل والوزن فليخشَ الله تعالى، وليحذر من التطفيف.\nrefl\nوَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ\nأي: بما فيه صلاحه وتثميره؛ وذلك بحفظ أصوله، وتثمير فروعه. القرطبي:٩/١١١.\nكيف يكون إصلاح مال اليتيم؟\nوَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ حَتَّىٰ يَبۡلُغَ أَشُدَّهُۥۚ\nووجه تخصيص حق اليتيم في ماله بالحفظ أن ذلك الحق مظنة الاعتداء عليه من الولي، وهو مظنة انعدام المدافع عنه. ابن عاشور:٨/١٦٤.\nما وجه تخصيص حق اليتيم في ماله بالحفظ في الآية الكريمة؟\nوَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ بِٱلۡقِسۡطِۖ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَاۖ\nأي: بقدر ما تسعه ولا تضيق عنه، فمن حرص على الإيفاء في الكيل والوزن، ثم حصل منه تقصير لم يُفَرِّط فيه ولم يعلمه فإن الله عفو غفور. السعدي:٢٨٠.\nلم ذكر أنه لا تكلف نفسٌ إلا وسعها بعد ذكر الأمر بإيفاء الكيل والميزان؟\nوَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ ١٥٣\nوهذه السبل تعم اليهودية والنصرانية والمجوسية، وسائر أهل الملل، وأهل البدع والضلالات من أهل الأهواء والشذوذ في الفروع، وغير ذلك من أهل التعمق في الجدل، والخوض في الكلام؛ هذه كلها عُرضة للزلل، ومظنة لسوء المعتقد. القرطبي:٩/١١٧.\nما السبل التي حذرنا الله تعالى من اتباعها؟\nوَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ ذَٰلِكُمۡ وَصَّىٰكُم بِهِۦ لَعَلَّكُمۡ تَتَّقُونَ ١٥٣\n﴿وَلَا تَتَّبِعُواْ ٱلسُّبُلَ﴾: الطرق المختلفة في الدين من: اليهودية، والنصرانية، وغيرها من الأديان الباطلة، ويدخل فيه أيضًا البدع والأهواء المضلة، وفي الحديث: أن النبي -صلّى الله عليه وسلّم- خط خطا، ثم قال: «هذا سبيل الله»، ثم خط خطوطًا عن يمينه وعن شماله، ثم قال: «هذه كلها سبل؛ على كل سبيل منها شيطان يدعو إليه». ابن جزي:١/٢٩٢.\nما رأيك في الانتماء لبعض الفرق المخالفة لمنهج أهل السنة بحجة أن فيها بعض الخير؟\nوَأَنَّ هَٰذَا صِرَٰطِي مُسۡتَقِيمٗا فَٱتَّبِعُوهُۖ وَلَا تَتَّبِعُواْ ٱلسُّبُلَ فَتَفَرَّقَ بِكُمۡ عَن سَبِيلِهِۦۚ\nإنَّما وحَّد سبيله لأن الحق واحد، ولهذا جمع السبل؛ لتفرقها، وتشعبها. ابن كثير:٢/١٨٢.\nلم جاء لفظ سبيل الله مفردًا، ولفظ سبل غير الله مجموعًا؟\nوَهَٰذَا كِتَٰبٌ أَنزَلۡنَٰهُ مُبَارَكٞ\nتستخرج منه البركات؛ فما من خير إلا وقد دعا إليه، ورغَّب فيه، وذكر الحكم والمصالح التي تحث عليه، وما من شر إلا وقد نهى عنه، وحَذَّر منه، وذكر الأسباب المنفرة عن فعله، وعواقبها الوخيمة. السعدي:٢٨١.\nما وجوه البركة التي تضمنها هذا الكتاب العزيز؟"],[150,"§الأنعام\nwords\nشِيَعًافِرَقًا، وَأَحزَابًا.\nقِيَمًاقَائِمًا بِأَمرِ الدُّنيَا وَالآخِرَةِ.\nوَنُسُكِيذَبحِي.\nوَلاَ تَزِرُلاَ تَحمِلُ.\nوَازِرَةٌنَفسٌ آثِمَةٌ.\nوِزرَإِثمَ.\ndeeds\nانصح بعض عبّاد القبور بأن العبادة لا تصرف لغير الله، مستدلًا بهذه الآية.\nسل الله تعالى الإخلاص في جميع أمورك، ولا تعمل عملًا إلا وأنت مستحضر فيه إخلاص النية.\nأحسن إلى فقير.\nguid\nلا تُسَوِّف التوبة والأعمال الصالحة؛ فقد يأتي عليك زمان لا تُمَكَّن فيه منها.\nخالف المشركين واجعل ذبحك لله تعالى وحده.\nعلى الداعية أن يُنَوِّع أساليب دعوته؛ فمرةً يرهب الناس من عذاب الله وعقابه، وأخرى يرغبهم فيما عنده من النعيم والرضوان، وثالثة يجمع بينهما.\nrefl\nيَوۡمَ يَأۡتِي بَعۡضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفۡسًا إِيمَٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرٗاۗ قُلِ ٱنتَظِرُوٓاْ إِنَّا مُنتَظِرُونَ ١٥٨\nقال العلماء: وإنَّما لا ينفع نفسًا إيمانها عند طلوعها من مغربها لأنه خلص إلى قلوبهم من الفزع ما تخمد معه كل شهوة من شهوات النفس، وتفتر كل قوة من قوى البدن؛ فيصير الناس كلهم -لإيقانهم بدنو القيامة- في حال من حضره الموت في انقطاع الدواعي إلى أنواع المعاصي عنهم، وبطلانها من أبدانهم، فمن تاب في مثل هذه الحال لم تقبل توبته كما لا تقبل توبة من حضره الموت. القرطبي:٩/١٣٠.\nلماذا لا ينفع الإيمان إذا طلعت الشمس من مغربها؟\nيَوۡمَ يَأۡتِي بَعۡضُ ءَايَٰتِ رَبِّكَ لَا يَنفَعُ نَفۡسًا إِيمَٰنُهَا لَمۡ تَكُنۡ ءَامَنَتۡ مِن قَبۡلُ أَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرٗاۗ\nوالحكمة في هذا ظاهرة، فإنه إنَّما كان الإيمان ينفع إذا كان إيمانًا بالغيب، وكان اختيارًا من العبد، فأما إذا وجدت الآياتُ صار الأمر شهادة، ولم يبق للإيمان فائدة؛ لأنه يشبه الإيمان الضروري؛ كإيمان الغريق والحريق ونحوهما ممن إذا رأى الموتَ أقلع عَمَّا هو فيه. السعدي:٢٨١.\nمن خلال الآية بيّن -باختصار- أهمية الإيمان بالغيب.\nأَوۡ كَسَبَتۡ فِيٓ إِيمَٰنِهَا خَيۡرٗاۗ\nالإنسان يكتسب الخير بإيمانه؛ فالطاعة والبر والتقوى إنَّما تنفع وتنمو إذا كان مع العبد الإيمان، فإذا خلا القلب من الإيمان لم ينفعه شيء من ذلك. السعدي:٢٨٢.\nقد يعمل المشركون بعض أعمال الخير في الدنيا، فهل يفيدون منها في الآخرة؟ ولماذا؟\nإِنَّ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعٗا لَّسۡتَ مِنۡهُمۡ فِي شَيۡءٍۚ\nقال مجاهد في قوله تعالى: ﴿إِنَّ ٱلَّذِينَ فَرَّقُواْ دِينَهُمۡ وَكَانُواْ شِيَعًا﴾ قال: \"هم أهل البدع والشبهات؛ فهم في أمور مبتدعة في الشرع، مشتبهة في العقل\". ابن تيمية:٣/١١٧.\nهل يدخل أهل البدع في هذه الآية الكريمة؟\nقُلۡ إِنَّنِي هَدَىٰنِي رَبِّيٓ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٖ دِينٗا قِيَمٗا مِّلَّةَ إِبۡرَٰهِيمَ حَنِيفٗاۚ وَمَا كَانَ مِنَ ٱلۡمُشۡرِكِينَ ١٦١ قُلۡ إِنَّ صَلَاتِي وَنُسُكِي وَمَحۡيَايَ وَمَمَاتِي لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ١٦٢\nوهذا عموم، ثم خَصَّص من ذلك أشرف العبادات فقال: ﴿قُلۡ إِنَّ صَلَاتِي وَنُسُكِي﴾ أي: ذبحي؛ وذلك لشرف هاتين العبادتين وفضلهما، ودلالتهما على محبة الله تعالى، وإخلاص الدين له، والتقرب إليه بالقلب واللسان والجوارح، وبالذبح الذي هو بذل ما تحبه النفس من المال لما هو أحب إليها؛ وهو الله تعالى. السعدي:٢٨٢.\nالصلاة والنسك داخلة في الآية الأولى؛ فلماذا أفردهما بالذكر؟\nقُلۡ إِنَّ صَلَاتِي وَنُسُكِي وَمَحۡيَايَ وَمَمَاتِي لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ ١٦٢\nأي: حياتي ووفاتي ﴿لِلَّهِ رَبِّ ٱلۡعَٰلَمِينَ﴾ أي: هو يحييني، ويميتني، وقيل: محياي بالعمل الصالح، ومماتي إذا مت على الإيمان لله رب العالمين. البغوي:٢/٨٦.\nكيف يكون المحيا والممات لله رب العالمين؟\nإِنَّ رَبَّكَ سَرِيعُ ٱلۡعِقَابِ وَإِنَّهُۥ لَغَفُورٞ رَّحِيمُۢ ١٦٥\nترهيب وترغيب أن حسابه وعقابه سريع فيمن عصاه، وخالف رسله، وإنه لغفور رحيم لمن والاه، واتبع رسله فيما جاؤوا به من خبر وطلب... فتارة يدعو عباده إليه بالرغبة، وصفة الجنة، والترغيب فيما لديه، وتارة يدعوهم إليه بالرهبة، وذكر النار وأنكالها وعذابها، والقيامة وأهوالها، وتارة بهما. ابن كثير:٢/١٩١.\nلماذا تكون الدعوة مرة بالترهيب، ومرة بالترغيب، ومرة بهما؟"],[151,"§الأعراف\nwords\nبَأسُنَاعَذَابُنَا.\nبَيَاتًانَائِمِينَ لَيلًا.\nقَائِلُونَنَائِمُونَ فِي نِصفِ النَّهَارِ.\nوَالوَزنُوَزنُ أَعمَالِ العِبَادِ.\nمَعَايِشَمَا تَعِيشُونَ بِهِ.\ndeeds\nقل: \"اللهم احفظني من بين يديّ ومن خلفي، وعن يميني وعن شمالي، ومن فوقي، وأعوذ بعظمتك أن أُغتال من تحتي\".\nاذكر الله تعالى دائمًا؛ وخصوصًا وقت غفلة الخلق.\nاعترف اليوم بينك وبين ربك بظلمك وخطئك، وأصلحه، وتب منه، فالاعتراف والتوبة عند نزول العذاب لا قيمة لها.\nguid\nالمداومة على قراءة هذا القرآن وتدبره سبيلٌ لتذكر الأعمال الصالحة، ولإصلاح الظاهر والباطن.\nوجوب اتباع الوحي، وحرمة اتباع ما يدعو إليه أصحاب الأهواء والمبتدعة.\nالاعتبار بما حل بالدول الفاسدة والظالمة من خراب ودمار.\nrefl\nالٓمٓصٓ ١ كِتَٰبٌ أُنزِلَ إِلَيۡكَ فَلَا يَكُن فِي صَدۡرِكَ حَرَجٞ مِّنۡهُ لِتُنذِرَ بِهِۦ وَذِكۡرَىٰ لِلۡمُؤۡمِنِينَ ٢\nالحروف المقطعة في أوائل السور أعقبت بذكر القرآن، أو الوحي، أو ما في معنى ذلك؛ وذلك يرجح أن المقصود من هذه الحروف التهجي إبلاغًا في التحدي للعرب بالعجز عن الإتيان بمثل القرآن. ابن عاشور:٨/١٠.\nلماذا يأتي ذكر الكتاب بعد ذكر الحروف المقطعة غالبًا؟\nٱتَّبِعُواْ مَآ أُنزِلَ إِلَيۡكُم مِّن رَّبِّكُمۡ وَلَا تَتَّبِعُواْ مِن دُونِهِۦٓ أَوۡلِيَآءَۗ قَلِيلٗا مَّا تَذَكَّرُونَ ٣\nودلت الآية على ترك اتباع الآراء مع وجود النص. القرطبي:٩/١٥١.\nما التوجيه القرآني لمن يترك اتباع الدليل لأجل الأفكار والآراء؟\nوَكَم مِّن قَرۡيَةٍ أَهۡلَكۡنَٰهَا فَجَآءَهَا بَأۡسُنَا بَيَٰتًا أَوۡ هُمۡ قَآئِلُونَ ٤\nأي: فكان منهم من جاءه أمر الله وبأسه ونقمته (بياتًا) أي: ليلًا، ﴿أَوۡ هُمۡ قَآئِلُونَ﴾: من القيلولة؛ وهي الاستراحة وسط النهار. وكلا الوقتين وقت غفلة ولهو. ابن كثير:٢/١٩٢.\nلماذا خُصَّ هذان الوقتان بنُزول العذاب فيهما؟\nفَمَا كَانَ دَعۡوَىٰهُمۡ إِذۡ جَآءَهُم بَأۡسُنَآ إِلَّآ أَن قَالُوٓاْ إِنَّا كُنَّا ظَٰلِمِينَ ٥\nوإنَّما جعل تكذيبهم ظلمًا لأنه تكذيب ما قامت الأدلة على صدقه، فتكذيبه ظلم للأدلة. ابن عاشور:٨/٣٢.\nتكذيب ما قامت الأدلة على صدقه نوع من الظلم، بين ذلك.\nفَلَنَسۡـَٔلَنَّ ٱلَّذِينَ أُرۡسِلَ إِلَيۡهِمۡ وَلَنَسۡـَٔلَنَّ ٱلۡمُرۡسَلِينَ ٦\nاتفق أهل العلم -أهل الكتاب والسنة- على أن كل شخص سوى الرسول فإنه يؤخذ من قوله ويُترك، إلا رسول الله -صلى الله عليه وسلم-؛ فإنه يجب تصديقه في كل ما أخبر، وطاعته في كل ما أمر؛ فإنه المعصوم الذي لا ينطق عن الهوى، إن هو إلا وحي يوحى، وهو الذي يُسأل الناس عنه يوم القيامة؛ كما قال تعالى: ﴿فَلَنَسۡـَٔلَنَّ ٱلَّذِينَ أُرۡسِلَ إِلَيۡهِمۡ وَلَنَسۡـَٔلَنَّ ٱلۡمُرۡسَلِينَ﴾. ابن تيمية:٣/١٣٧.\nمن علاج التعصب المقيت أن تعلم أن كل شخص سوى الرسول يؤخذ من قوله ويترك، وضح ذلك.\nوَٱلۡوَزۡنُ يَوۡمَئِذٍ ٱلۡحَقُّۚ فَمَن ثَقُلَتۡ مَوَٰزِينُهُۥ فَأُوْلَٰٓئِكَ هُمُ ٱلۡمُفۡلِحُونَ ٨\nفإن قلت: أليس الله -عز وجل- يعلم مقادير أعمال العباد؟ فما الحكمة في وزنها؟! قلت: فيه حكم، منها: إظهار العدل، وأن الله -عز وجل- لا يظلم عباده... ومنها: تعريف العباد ما لهم من خير وشر، وحسنة وسيئة. القاسمي:١/٢٩٧.\nما الحكمة من وزن الأعمال مع علم الله تعالى بها؟\nوَلَقَدۡ خَلَقۡنَٰكُمۡ ثُمَّ صَوَّرۡنَٰكُمۡ ثُمَّ قُلۡنَا لِلۡمَلَٰٓئِكَةِ ٱسۡجُدُواْ لِأٓدَمَ فَسَجَدُوٓاْ إِلَّآ إِبۡلِيسَ لَمۡ يَكُن مِّنَ ٱلسَّٰجِدِينَ ١١\nينبه تعالى بني آدم في هذا المقام على شرف أبيهم آدم، ويبين لهم عداوة عدوهم إبليس، وما هو منطوٍ عليه من الحسد لهم ولأبيهم؛ ليحذروه، ولا يتبعوا طرائقه. ابن كثير:٢/١٩٣.\nما الذي يفيده المسلم من عدم سجود إبليس لأبيه آدم؟"],[152,"§الأعراف\nwords\nالصَّاغِرِينَالحَقِيرِينَ، الذَّلِيلِينَ.\nمَذؤومًامَمقُوتًا، مَذمُومًا.\nمَدحُورًامَطرُودًا.\nوَطَفِقَاشَرَعَا، وَأَخَذَا.\nيَخصِفَانِيُلزِقَانِ.\ndeeds\nاعمل اليوم عملًا فيه تواضع مع الآخرين واجتناب للكبر.\nتذكر صفاتٍ ونعمًا ميزك الله بها على الآخرين، وانسب الفضل فيها لله تعالى وحده.\nأكثر اليوم من الاستعاذة بالله من الشيطان الرجيم، وقول: \"اللهم احفظني من بين يديّ ومن خلفي، وعن يميني وعن شمالي، ومن فوقي، وأعوذ بعظمتك أن أُغتال من تحتي\".\nguid\nقصة آدم مع إبليس تؤكد أن هذا العدو قد أعد لك عدته، فأعد أنت العدة لرد مكائده.\nسلاح إبليس الذي يحارب به ابن آدم هو الوسوسة والتزيين لا غير.\nليس كل من يقسم بالله تعالى مدعيًا النصح يكون صادقًا؛ فتاريخ المقسم يبيّن حقيقته.\nrefl\nقَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ ١٢\n﴿قَالَ أَنَا۠ خَيۡرٌ مِّنۡهُ﴾: تعليلٌ علَّلَ به إبليس امتناعه من السجود، وهو يقتضي الاعتراض على الله تعالى في أمره بسجود الفاضل للمفضول على زعمه، وبهذا الاعتراض كفر إبليس؛ إذ ليس كفره كفر جحود. ابن جزي:١/٢٩٧.\nيبلغ غرور المخلوق بعقله أحيانًا أن يرد به على الشرع؛ فيكفر بذلك، وضح ذلك من الآية.\nقَالَ مَا مَنَعَكَ أَلَّا تَسۡجُدَ إِذۡ أَمَرۡتُكَۖ قَالَ أَنَا۠ خَيۡرٞ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ ١٢\nحجة إبليس في قوله: ﴿أَنَا۠ خَيۡرٌ مِّنۡهُ خَلَقۡتَنِي مِن نَّارٍ وَخَلَقۡتَهُۥ مِن طِينٍ﴾ هي باطلة؛ لأنه عارض النص بالقياس. ابن تيمية:٣/١٨٣.\nلماذا كانت حجة إبليس باطلة؟\nخَلَقۡتَنِي مِن نَّارٖ وَخَلَقۡتَهُۥ مِن طِينٖ ١٢\nكَذب في تفضيل مادة النار على مادة الطين والتراب؛ فإن مادة الطين فيها الخشوع والسكون والرزانة، ومنها تظهر بركات الأرض من الأشجار وأنواع النبات على اختلاف أجناسه وأنواعه، وأمَّا النار ففيها الخفة والطيش والإحراق. السعدي:٢٨٤.\nأخطأ إبليس في جعل مادة النار أفضلَ من مادة الطين، فما وجه الخطأ؟\nقَالَ فَٱهۡبِطۡ مِنۡهَا فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ ١٣\n﴿فَمَا يَكُونُ لَكَ أَن تَتَكَبَّرَ فِيهَا﴾: لأن أهلها الملائكة المتواضعون، ﴿فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ﴾ أي: الأذلين، ودل هذا على أن من عصى مولاه فهو ذليل. القرطبي:٩/١٦٩.\nما صفة المقربين من الله، وما صفة المبعدين عنه سبحانه؟\nفَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ ١٣\n﴿فَٱخۡرُجۡ إِنَّكَ مِنَ ٱلصَّٰغِرِينَ﴾ أي: الذليلين الحقيرين؛ معاملة له بنقيض قصده، مكافأة لمراده بضده. ابن كثير:٢/١٩٥.\nلماذا كانت عاقبة إبليس بالذِّلَّة والصَّغَار؟\nثُمَّ لَأٓتِيَنَّهُم مِّنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ وَعَنۡ أَيۡمَٰنِهِمۡ وَعَن شَمَآئِلِهِمۡۖ وَلَا تَجِدُ أَكۡثَرَهُمۡ شَٰكِرِينَ ١٧\nقال ابن عباس وعكرمة في قوله تعالى عن إبليس: ﴿ثُمَّ لَأٓتِيَنَّهُم مِّنۢ بَيۡنِ أَيۡدِيهِمۡ وَمِنۡ خَلۡفِهِمۡ وَعَنۡ أَيۡمَٰنِهِمۡ وَعَن شَمَآئِلِهِمۡۖ وَلَا تَجِدُ أَكۡثَرَهُمۡ شَٰكِرِينَ﴾، قال: \"ولم يقل: \"من فوقهم\"؛ لأنه علم أن الله من فوقهم\". ابن تيمية:٣/١٤٠.\nلماذا لم يقل الله تعالى حكاية عن قول إبليس: \"من فوقهم\"؟\nفَوَسۡوَسَ لَهُمَا ٱلشَّيۡطَٰنُ لِيُبۡدِيَ لَهُمَا مَا وُۥرِيَ عَنۡهُمَا مِن سَوۡءَٰتِهِمَا\n﴿مِن سَوۡءَٰتِهِمَا﴾: من عوراتهما، وسمي الفرج عورة؛ لأن إظهاره يسوء صاحبه، ودل هذا على قبح كشفها. القرطبي:٩/١٧٥.\nعلى أي شيء تدل تسمية الفرج بالعورة والسوأة؟"],[153,"§الأعراف\nwords\nيُوَارِي سَوآتِكُميَستُرُ عَورَاتِكُم، وَهُوَ لِبَاسُ الضَّرُورَةِ.\nوَرِيشًالِبَاسَ الزِّينَةِ.\nيَفتِنَنَّكُمُيُضِلَّنَّكُم، وَيَخدَعَنَّكُم.\nبِالقِسطِبِالعَدلِ.\ndeeds\nتذكر ذنبًا فعلته، ثم استغفر الله تعالى و تب إليه هذا اليوم سبعين مرة.\nقل هذا الدعاء العظيم في أوقات الإجابة هذا اليوم؛ فهو من دعوات المقربين.\nحافظ على أداء صلاة الفريضة في المسجد.\nguid\nمن ظلم نفسه فهو خاسر إن لم تشمله رحمة ربه ومغفرته.\nشؤم المعصية كان سبب طرد إبليس من الرحمة، وإخراج آدم من الجنة؛ فكن على حذرمنها.\nكن حذرًا من الشيطان، ولا تغفل عن المواضع التي يدخل عليك منها.\nrefl\nقَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ٢٣\nقال بعض الشيوخ: اثنان أذنبا ذنبًا: آدم وإبليس؛ فآدم تاب فتاب الله عليه، واجتباه وهداه، وإبليس أصر واحتج بالقدر؛ فمن تاب من ذنبه أشبه أباه آدم، ومن أصر واحتج بالقدر أشبه إبليس. ابن تيمية:٣/١٤٢.\nبيّن فضيلة سرعة الاعتراف بالذنب والاستغفار منه من خلال الآية.\nقَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ٢٣\nفالمغفرة إزالة السيئات، والرحمة إنزال الخيرات. ابن تيمية:٣/١٤٢.\nما الفرق بين المغفرة و الرحمة في الآية الكريمة؟\nقَالَا رَبَّنَا ظَلَمۡنَآ أَنفُسَنَا وَإِن لَّمۡ تَغۡفِرۡ لَنَا وَتَرۡحَمۡنَا لَنَكُونَنَّ مِنَ ٱلۡخَٰسِرِينَ ٢٣\nمن أشبه آدم؛ بالاعتراف، وسؤال المغفرة، والندم، والإقلاع إذا صدرت منه الذنوب، اجتباه الله وهداه. ومن أشبه إبليس إذا صدر منه الذنب، ولا يزال يزداد من المعاصي؛ فإنه لا يزداد من الله إلا بعدًا. السعدي:٢٨٥.\nفي قصة آدم وإبليس عبرةٌ عظيمةٌ لمن وقع في الذنب، فما هي؟\nوَلِبَاسُ ٱلتَّقۡوَىٰ ذَٰلِكَ خَيۡرٞۚ\nخير من اللباس الحسي؛ فإن لباس التقوى يستمر مع العبد، ولا يبلى، ولا يبيد، وهو جمال القلب والروح. وأمَّا اللباس الظاهري؛ فغايته أن يستر العورة الظاهرة في وقت من الأوقات، أو يكون جمالًا للإنسان، وليس وراء ذلك منه نفع. السعدي:٢٨٦.\nلماذا كان لباس التقوى خيرًا من اللباس الحسي؟\nإِنَّهُۥ يَرَىٰكُمۡ هُوَ وَقَبِيلُهُۥ مِنۡ حَيۡثُ لَا تَرَوۡنَهُمۡۗ\nقال مالك بن دينار: \"إن عدوًا يراك ولا تراه لشديد الخصومة والمؤنة، إلا من عصم الله\". البغوي:٢/٩٧.\nبيّن خطورة العدو الذي يراك ولا تراه.\nإِنَّا جَعَلۡنَا ٱلشَّيَٰطِينَ أَوۡلِيَآءَ لِلَّذِينَ لَا يُؤۡمِنُونَ ٢٧\nأي: زيادة في عقوبتهم، وسوينا بينهم في الذهاب عن الحق. القرطبي: ٩/٣٩٣.\nمن هم أولياء الشياطين؟\nإِنَّهُمُ ٱتَّخَذُواْ ٱلشَّيَٰطِينَ أَوۡلِيَآءَ مِن دُونِ ٱللَّهِ وَيَحۡسَبُونَ أَنَّهُم مُّهۡتَدُونَ ٣٠\nوفيه دليل على أن الهداية بفضل الله ومنِّه، وأن الضلالة بخذلانه للعبد إذا تولى -بجهله وظلمه- الشيطان، وتسبب لنفسه بالضلال، وأن من حسب أنه مهتد وهو ضال أنه لا عذر له. السعدي:٢٨٧.\nأكثر أهل الضلال والبدع يعتقدون أنهم على حق؛ فهل ينفعهم هذا؟"],[154,"§الأعراف\nwords\nزِينَتَكُمسَاتِرِينَ عَورَاتِكُم، مُتَزَيِّنِينَ.\nنَصِيبُهُمحَظُّهُم.\nمِنَ الكِتَابِمَا كَتَبَ عَلَيهِم فِي اللَّوحِ مِنَ العَذَابِ.\ndeeds\nتجمل وتزين اليوم في خروجك للصلاة عملًا بهذه الآية الكريمة.\nأرسل رسائل تحذر فيها من أصول المحرمات المذكورة في الآية الكريمة.\nأرسل رسالة تحذر فيها من الفتوى أو القول على الله بلا علم.\nguid\nلا تسرف في الأكل والشرب أو الإنفاق المالي؛ فإن الله لا يحب المسرفين.\nفرق بين ما تكرهه نفسك وما حرمه الله سبحانه؛ فإنه لا يَحِلُّ لأحدٍ أن يحرم شيئًا أباحه الله.\nحال الأمم كحال الأفراد؛ يحصل الهلاك عند انتشار المرض في أكثر الأمة، كما يهلك الفرد عندما يستشري المرض في أكثر جسمه.\nrefl\nيَٰبَنِيٓ ءَادَمَ خُذُواْ زِينَتَكُمۡ عِندَ كُلِّ مَسۡجِدٖ وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ ٣١\nقيل: المراد به الزينة زيادة على الستر؛ كالتجمل للجمعة بأحسن الثياب، وبالسواك والطيب، ﴿وَكُلُواْ وَٱشۡرَبُواْ وَلَا تُسۡرِفُوٓاْۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُسۡرِفِينَ﴾ أي: لا تكثروا من الأكل فوق الحاجة، وقال الأطباء: إن الطب كله مجموع في هذه الآية. ابن جزي:١/٣٠٠.\nجمعت هذه الآية بين ما يصلح القلوب وما يصلح الأبدان، وضح ذلك.\nقُلۡ مَنۡ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِيٓ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزۡقِۚ قُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا خَالِصَةٗ يَوۡمَ ٱلۡقِيَٰمَةِۗ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ٣٢\nهذا التوسيع من الله لعباده بالطيبات جعله لهم ليستعينوا به على عبادته، فلم يبحه إلا لعباده المؤمنين، ولهذا قال: (قل هي للذين آمنوا في الحياة الدنيا خالصة يوم القيامة) أي: لا تبعة عليهم فيها، ومفهوم الآية أن من لم يؤمن بالله، بل استعان بها على معاصيه، فإنها غير خالصة له، ولا مباحة، بل يعاقب عليها وعلى التنعم بها، ويسأل عن النعيم يوم القيامة. السعدي:٢٨٧.\nما الحكمة من إباحة الطيبات للمؤمنين؟\nقُلۡ مَنۡ حَرَّمَ زِينَةَ ٱللَّهِ ٱلَّتِيٓ أَخۡرَجَ لِعِبَادِهِۦ وَٱلطَّيِّبَٰتِ مِنَ ٱلرِّزۡقِۚ قُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا خَالِصَةٗ يَوۡمَ ٱلۡقِيَٰمَةِۗ كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ٣٢\nدلت الآية على لباس الرفيع من الثياب، والتجمل بها في الجمع والأعياد، وعند لقاء الناس، ومزاورة الإخوان. القرطبي:٩/٢٠٣.\nإن الله جميل يحب الجمال، وضح ذلك من الآية.\nقُلۡ هِيَ لِلَّذِينَ ءَامَنُواْ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا خَالِصَةٗ يَوۡمَ ٱلۡقِيَٰمَةِۗ\nهي خالصة يوم القيامة من التنغيص والغم للمؤمنين؛ فإنها لهم في الدنيا مع التنغيص والغم. البغوي:٢/١٠٠.\nكيف يكون المتاع الحسن يوم القيامة خالصًا للمؤمنين؟\nكَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَعۡلَمُونَ ٣٢ قُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ\n﴿كَذَٰلِكَ نُفَصِّلُ ٱلۡأٓيَٰتِ﴾ أي: نوضحها ونبينها، ﴿لِقَوۡمٍ يَعۡلَمُونَ﴾: لأنهم الذين ينتفعون بما فصله الله من الآيات، ويعلمون أنها من عند الله، فيعقلونها ويفهمونها. ثم ذكر المحرمات التي حرمها الله في كل شريعة من الشرائع؛ فقال: ﴿قُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ﴾ أي: الذنوب الكبار التي تستفحش وتستقبح لشناعتها وقبحها؛ وذلك كالزنا، واللواط، ونحوهما. السعدي:٢٨٧.\nلماذا خص أهل العلم بتفصيل الآيات؟\nقُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ وَٱلۡإِثۡمَ وَٱلۡبَغۡيَ بِغَيۡرِ ٱلۡحَقِّ وَأَن تُشۡرِكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنٗا وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ ٣٣\nأصول المحرمات التي قال الله فيها: ﴿قُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ وَٱلۡإِثۡمَ وَٱلۡبَغۡيَ بِغَيۡرِ ٱلۡحَقِّ وَأَن تُشۡرِكُواْ بِٱللَّهِ مَا لَمۡ يُنَزِّلۡ بِهِۦ سُلۡطَٰنًا وَأَن تَقُولُواْ عَلَى ٱللَّهِ مَا لَا تَعۡلَمُونَ﴾ مما اتفقت عليه شرائع الأنبياء. ابن تيمية:٣/١٥٧.\nما أصول المحرمات من خلال الآية الكريمة؟\nقُلۡ إِنَّمَا حَرَّمَ رَبِّيَ ٱلۡفَوَٰحِشَ مَا ظَهَرَ مِنۡهَا وَمَا بَطَنَ\nالقبح والحسن في المعاني إنَّما يُتلقى من جهة الشرع، والفاحش كذلك؛ فقوله هنا: (الفَواحِشَ) إنَّما هي إشارة إلى ما نص الشرع على تحريمه في مواضع أُخَرَ؛ فكل ما حرمه الشرع فهو فاحش وإن كان العقل لا ينكره؛ كلباس الحرير والذهب للرجال ونحوه. ابن عطية:٢/٣٩٥.\nما ميزان الحسن والقبح المؤثر في التحليل والتحريم؟"],[155,"§الأعراف\nwords\nادَّارَكُواتَلاَحَقُوا.\nيَلِجَيَدخُلَ.\nسَمِّ الخِيَاطِثُقبِ الإِبرَةِ.\nغَوَاشٍأَغطِيَةٌ تَغشَاهُم.\ndeeds\nأرسل رسالة تحذر فيها من اللعن؛ لأنه من صفات أهل النار.\nإذا خرجت من منزلك فقل: \"اللهم إني أعوذ بك أن أَضِلَّ أو أُضَلَّ، أو أَزِلَّ أو أُزَلَّ، أو أَظلِم أو أُظلَم، أو أَجهَل أو يُجهَل عليَّ\".\nذكر من حولك بأهمية سلامة القلب، وأنه من صفات أهل الجنة.\nguid\nيلعن أصدقاء السوء بعضهم بعضًا يوم القيامة؛ لأن كل واحد كان سببًا في عذاب الآخر.\nلن ينفعك صاحب المال والجاه إذا اتبعته على ضلالِهِ، بل سيتبرأ منك في الآخرة.\nالالتزام بشرع الله سهل ومتيسر، فاستعن بالله ولا تعجز.\nrefl\nقَالَ ٱدۡخُلُواْ فِيٓ أُمَمٖ قَدۡ خَلَتۡ مِن قَبۡلِكُم مِّنَ ٱلۡجِنِّ وَٱلۡإِنسِ فِي ٱلنَّارِۖ كُلَّمَا دَخَلَتۡ أُمَّةٞ لَّعَنَتۡ أُخۡتَهَاۖ حَتَّىٰٓ إِذَا ٱدَّارَكُواْ فِيهَا جَمِيعٗا قَالَتۡ أُخۡرَىٰهُمۡ لِأُولَىٰهُمۡ رَبَّنَا هَٰٓؤُلَآءِ أَضَلُّونَا فَـَٔاتِهِمۡ عَذَابٗا ضِعۡفٗا مِّنَ ٱلنَّارِۖ قَالَ لِكُلّٖ ضِعۡفٞ وَلَٰكِن لَّا تَعۡلَمُونَ ٣٨\nفيما قص الله من محاورة قادة الأمم وأتباعهم ما فيه موعظة وتحذير لقادة المسلمين من الإيقاع بأتباعهم فيما يزج بهم في الضلالة، ويحسن لهم هواهم، وموعظة لعامتهم من الاسترسال في تأييد من يشايع هواهم، ولا يبلغهم النصيحة. ابن عاشور:٨/١٢٥.\nماذا يفاد من حكاية محاورة القادة مع أتباعهم في الآية الكريمة؟\nقَالَ لِكُلّٖ ضِعۡفٞ وَلَٰكِن لَّا تَعۡلَمُونَ ٣٨\nأي: لا يعلم كل فريق ما بالفريق الآخر؛ إذ لو علم بعض من في النار أن عذاب أحد فوق عذابه، لكان نوع سلوة له. القرطبي:٩/٢٢٢.\nلماذا أخفى الله تعالى عذاب أهل النار بعضهم عن بعض؟\nإِنَّ ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَا وَٱسۡتَكۡبَرُواْ عَنۡهَا لَا تُفَتَّحُ لَهُمۡ أَبۡوَٰبُ ٱلسَّمَآءِ وَلَا يَدۡخُلُونَ ٱلۡجَنَّةَ حَتَّىٰ يَلِجَ ٱلۡجَمَلُ فِي سَمِّ ٱلۡخِيَاطِۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُجۡرِمِينَ ٤٠\nومفهوم الآية أن أرواح المؤمنين المنقادين لأمر الله المصدقين بآياته تفتح لها أبواب السماء حتى تعرج إلى الله، وتصل إلى حيث أراد الله من العالم العلوي، وتبتهج بالقرب من ربها والحظوة برضوانه. السعدي:٢٨٨.\nماذا تفيد من الإخبار بإغلاق أبواب السماء عن أرواح الكافرين؟\nلَهُم مِّن جَهَنَّمَ مِهَادٞ وَمِن فَوۡقِهِمۡ غَوَاشٖۚ وَكَذَٰلِكَ نَجۡزِي ٱلظَّٰلِمِينَ ٤١\n﴿لَهُم مِّن جَهَنَّمَ مِهَادٌ﴾ أي: فراش، ﴿وَمِن فَوۡقِهِمۡ غَوَاشٍۚ﴾ أي: لُحُف، وهي جمع غاشية؛ يعني: ما غشاهم وغطاهم؛ يريد إحاطة النار بهم من كل جانب. البغوي:٢/١٠٣.\nكما أن النعيم الحرام يعم جسد صاحبه في الدنيا، كذلك يعمه العذاب يوم القيامة، وضح ذلك.\nوَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ لَا نُكَلِّفُ نَفۡسًا إِلَّا وُسۡعَهَآ\n﴿وَٱلَّذِينَ ءَامَنُواْ وَعَمِلُواْ ٱلصَّٰلِحَٰتِ﴾ أي: آمنت قلوبهم، وعملوا الصالحات بجوارحهم؛ ضد أولئك الذين كفروا بآيات الله، واستكبروا عنها. وينبه تعالى على أن الإيمان والعمل به سهل؛ لأنه تعالى قال لا نكلف نفسا إلا وسعها. ابن كثير:٢/٢٠٥.\nالمانع من الإيمان والهداية ليس صعوبتهما، وضح ذلك من الآية.\nوَنَزَعۡنَا مَا فِي صُدُورِهِم مِّنۡ غِلّٖ تَجۡرِي مِن تَحۡتِهِمُ ٱلۡأَنۡهَٰرُۖ\nيقول تعالى ذكره: وأذهبنا من صدور هؤلاء الذين وصف صفتهم، وأخبر أنهم أصحاب الجنة، ما فيها من حقد وغمر وعداوة كان من بعضهم في الدنيا على بعض، فجعلهم في الجنة إذا أُدخلوها على سرر متقابلين، لا يحسد بعضهم بعضًا على شيء خص الله به بعضهم، وفضله من كرامته عليه، تجري من تحتهم أنهار الجنة. الطبري:١٢/٤٣٧.\nمن سعادة الإنسان ترك الغل والحسد، بين ذلك من خلال الآية.\nوَقَالُواْ ٱلۡحَمۡدُ لِلَّهِ ٱلَّذِي هَدَىٰنَا لِهَٰذَا وَمَا كُنَّا لِنَهۡتَدِيَ لَوۡلَآ أَنۡ هَدَىٰنَا ٱللَّهُۖ\nالذي يعمل الحسنات، إذا عملها فنفس عمله الحسنات هو من إحسان الله، وبفضله عليه بالهداية والإيمان؛ كما قال أهل الجنة: (الحمد لله الذي هدانا لهذا وما كنا لنهتدي لولا أن هدانا الله). ابن تيمية:٣/١٦٢.\nعمل الحسنات هو إحسان من الله تعالى، بيّن ذلك من الآية الكريمة."],[156,"§الأعراف\nwords\nحِجَابٌحَاجِزٌ، وَهُوَ سُورٌ بَينَهُمَا، يُقَالُ لَهُ: (الأَعرَافُ).\nبِسِيمَاهُمبِعَلاَمَاتِهِم.\nتِلقَاءَجِهَةَ.\nأَصحَابُ الأَعرَافِمَنِ استَوَت حَسَنَاتُهُم وَسَيِّئَاتُهُم.\ndeeds\nاقرأ كتابًا في صفات أهل الجنة وأهل النار.\nاسق ظمآنَ، واجعلها عادة لك، لعل الله ينفعك بها في الآخرة.\nحدد أمورًا شرعية تحس أنك لم تأخذها بجدية وحاول تعديلها إلى ما يرضي الله تعالى.\nguid\nمن صفات الظالمين أنهم يبغون دين الله عوجًا بتحريفه، وتغريب المجتمع، وهدم الفضيلة، وتشكيك الناس في دينهم، وتقديس الكفار.\nلن يغني عنك يوم القيامة كثرة مالك أو أتباعك، ولا كثرة أقاربك أو عشيرتـك، ولن ينفعك جاهك ولا سلطانك، لن ينفعك إلا عملـك.\nلا تحتقر شخصًا لأجل فقره وضعف دنياه.\nrefl\nوَنَادَىٰٓ أَصۡحَٰبُ ٱلۡجَنَّةِ أَصۡحَٰبَ ٱلنَّارِ أَن قَدۡ وَجَدۡنَا مَا وَعَدَنَا رَبُّنَا حَقّٗا فَهَلۡ وَجَدتُّم مَّا وَعَدَ رَبُّكُمۡ حَقّٗاۖ قَالُواْ نَعَمۡۚ فَأَذَّنَ مُؤَذِّنُۢ بَيۡنَهُمۡ أَن لَّعۡنَةُ ٱللَّهِ عَلَى ٱلظَّٰلِمِينَ ٤٤\nوهذا النداء من أهل الجنة لأهل النار تقريع، وتوبيخ، وزيادة في الكرب. ابن عطية: ٢/٤٠٢.\nما فائدة نداء أهل الجنة لأهل النار؟\nوَهُم بِٱلۡأٓخِرَةِ كَٰفِرُونَ ٤٥\nوهذا الذي أوجب لهم الانحراف عن الصراط، والإقبال على شهوات النفوس المحرمة، عدم إيمانهم بالبعث، وعدم خوفهم من العقاب ورجائهم للثواب. السعدي: ٢٩٠.\nما أثر الإيمان بالبعث والآخرة؟\nوَبَيۡنَهُمَا حِجَابٞۚ وَعَلَى ٱلۡأَعۡرَافِ رِجَالٞ يَعۡرِفُونَ كُلَّۢا بِسِيمَىٰهُمۡۚ وَنَادَوۡاْ أَصۡحَٰبَ ٱلۡجَنَّةِ أَن سَلَٰمٌ عَلَيۡكُمۡۚ لَمۡ يَدۡخُلُوهَا وَهُمۡ يَطۡمَعُونَ ٤٦\nبين أصحاب الجنة وأصحاب النار حجاب يقال له: (الأعراف) لا من الجنة ولا من النار، يشرف على الدارين، وينظر من عليه حال الفريقين، وعلى هذا الحجاب رجال يعرفون كلًّا من أهل الجنة والنار (بسيماهم) أي: علاماتهم التي بها يعرفون ويميزون، فإذا نظروا إلى أهل الجنة نادوهم: ﴿أَن سَلَٰمٌ عَلَيۡكُمۡۚ﴾ أي: يحيُّونهم ويسلِّمون عليهم، وهم إلى الآن لم يدخلوا الجنة، ولكنهم يطمعون في دخولها، ولم يجعل الله الطمع في قلوبهم إلا لما يريد بهم من كرامته. السعدي:٢٩٠.\nما المراد بأصحاب الأعراف؟\nوَنَادَىٰٓ أَصۡحَٰبُ ٱلۡأَعۡرَافِ رِجَالٗا يَعۡرِفُونَهُم بِسِيمَىٰهُمۡ قَالُواْ مَآ أَغۡنَىٰ عَنكُمۡ جَمۡعُكُمۡ وَمَا كُنتُمۡ تَسۡتَكۡبِرُونَ ٤٨\n﴿وَنَادَىٰٓ أَصۡحَٰبُ ٱلۡأَعۡرَافِ رِجَالًا﴾ كانوا عظماء في الدنيا من أهل النار، (يعرفونهم بسيماهم قالوا ما أغنى عنكم جمعكم) في الدنيا من المال والولد، ﴿وَمَا كُنتُمۡ تَسۡتَكۡبِرُونَ﴾ عن الإيمان. قال الكلبي: \"نادوهم وهم على السور: يا وليد بن المغيرة، يا أبا جهل بن هشام، يا فلان، [وهم ينظرونهم في النار]، ثم ينظرون إلى الجنة فيرون فيها الفقراء والضعفاء ممن كانوا يستهزئون بهم؛ مثل سلمان، وصهيب، وخباب، وبلال\". البغوي:٢/١٠٦.\nموازين الدنيا غير موازين الآخرة، وضح ذلك من خلال الآية.\nأَهَٰٓؤُلَآءِ ٱلَّذِينَ أَقۡسَمۡتُمۡ لَا يَنَالُهُمُ ٱللَّهُ بِرَحۡمَةٍۚ\nمن كلام أصحاب الأعراف خطابًا لأهل النار، والإشارة بهؤلاء إلى أهل الجنة؛ وذلك أن الكفار كانوا في الدنيا يقسمون أن الله لا يرحم المؤمنين، ولا يعبأ بهم؛ فظهر خلاف ما قالوا. ابن جزي:١/٣٦٠.\nاستخرج من هذه الآية بعض أسباب دخول النار.\nوَنَادَىٰٓ أَصۡحَٰبُ ٱلنَّارِ أَصۡحَٰبَ ٱلۡجَنَّةِ أَنۡ أَفِيضُواْ عَلَيۡنَا مِنَ ٱلۡمَآءِ أَوۡ مِمَّا رَزَقَكُمُ ٱللَّهُۚ قَالُوٓاْ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلۡكَٰفِرِينَ ٥٠\nفي هذه الآية دليل على أن سقي الماء من أفضل الأعمال، وقد سئل ابن عباس: أي الصدقة أفضل؟ فقال: \"الماء\"؛ ألم تروا إلى أهل النار حين استغاثوا بأهل الجنة: ﴿أَنۡ أَفِيضُواْ عَلَيۡنَا مِنَ ٱلۡمَآءِ أَوۡ مِمَّا رَزَقَكُمُ ٱللَّهُۚ﴾... وقد قال بعض التابعين: \"من كثرت ذنوبه؛ فعليه بسقي الماء\"، وقد غفر الله ذنوب الذي سقى الكلب؛ فكيف بمن سقى رجلًا مؤمنًا موحدًا وأحياه؟! القرطبي: ٩/٢٣٣.\nبيّن ما يدل على فضل سقي الماء.\nوَنَادَىٰٓ أَصۡحَٰبُ ٱلنَّارِ أَصۡحَٰبَ ٱلۡجَنَّةِ أَنۡ أَفِيضُواْ عَلَيۡنَا مِنَ ٱلۡمَآءِ أَوۡ مِمَّا رَزَقَكُمُ ٱللَّهُۚ قَالُوٓاْ إِنَّ ٱللَّهَ حَرَّمَهُمَا عَلَى ٱلۡكَٰفِرِينَ ٥٠\nوالأشنع على الكافرين في هذه المقالة أن يكون بعضهم يرى بعضًا؛ فإنه أخزى وأنكى للنفس. ابن عطية:٢/٤٠٦.\nفي النار عذاب حسي وآخر معنوي، وضح ذلك من خلال الآية."],[157,"§الأعراف\nwords\nاستَوَىعَلاَ، وَارتَفَعَ.\nحَثِيثًاسَرِيعًا، دَائِمًا.\nوَخُفيَةًسِرًّا.\nأَقَلَّتحَمَلَت.\nثِقَالًامُحَمَّلَةً بِالمَاءِ.\nلِبَلَدٍمَيِّتٍ لِبَلَدٍ مُجدِبٍ.\ndeeds\nادع الله تعـالى بتضرع دون أن يعلم بك أحد.\nإذا مشيت في طريقك؛ فأَمِط الأذى، وإذا رأيت شيئًا قد فسد يمكن إصلاحه فعدِّله وأصلِحه قدر استطاعتك.\nحدد أفكارًا وطرقًا تدرب فيها نفسك على الإحسان إلى الناس، واسـأل الله أن تكون من أهل الإحسان.\nguid\nالهدى والرحمة والعلم إنَّما هي في كتاب الله الكريم.\nلا ينفع الإيمان عند معاينة الموت والعذاب كما لا ينفع يوم القيامة.\nإذا أردت رحمة الله تعالى فكن من المحسنين.\nrefl\nوَلَقَدۡ جِئۡنَٰهُم بِكِتَٰبٖ فَصَّلۡنَٰهُ عَلَىٰ عِلۡمٍ\n﴿عَلَىٰ عِلۡمٍ﴾ من الله بأحوال العباد في كل زمان ومكان، وما يصلح لهم وما لا يصلح، ليس تفصيله تفصيل غير عالم بالأمور، فتجهله بعض الأحوال، فيحكم حكمًا غير مناسب، بل تفصيل من أحاط علمه بكل شيء، ووسعت رحمته كل شيء. السعدي:٢٩١.\nكيف ترد على من يزعم أن الشريعة الإسلامية ليست مناسبة لهذا الزمان؟\nٱدۡعُواْ رَبَّكُمۡ تَضَرُّعٗا وَخُفۡيَةًۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ ٥٥\nوالشريعة مقررة أن السر فيما لم يفترض من أعمال البر أعظم أجرًا من الجهر... قال الحسن بن أبي الحسن: \"لقد أدركنا أقوامًا ما كان على الأرض عمل يقدرون على أن يكون سرًا فيكون جهرًا أبدًا، ولقد كان المسلمون يجتهدون في الدعاء فلا يسمع لهم صوت، إن هو إلا الهمس بينهم وبين ربهم\". القرطبي:٩/٢٤٤-٢٤٥.\nهل عبادة السر أفضل، أم عبادة العلانية؟\nٱدۡعُواْ رَبَّكُمۡ تَضَرُّعٗا وَخُفۡيَةًۚ إِنَّهُۥ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ ٥٥\nيقول تعالى ذكره: ادعوا أيها الناس ربكم وحده، فأخلصوا له الدعاء، دون ما تدعون من دونه من الآلهة والأصنام، (تضرعًا) يقول: تذللًا واستكانةً لطاعته (وخفية)... لا جهارًا ومراءاةً، وقلوبكم غير موقنة بوحدانيته وربوبيته؛ فعل أهل النفاق والخداع لله ولرسوله. الطبري:١٢/٤٨٥.\nما الصفات التي ينبغي أن يجمعها المؤمن حال الدعاء؟\nوَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَا\nومن تدبر أحوال العالم وجد كل صلاح في الأرض فسببه توحيد الله وعبادته وطاعة رسوله، وكل شر في العالم وفتنة وبلاء وقحط وتسليط عدو وغير ذلك فسببه مخالفة الرسول والدعوة إلى غير الله. ابن تيمية:٣/١٧٠.\nما سبب كل صلاح؟ وما سبب كل فساد في الأرض؟\nوَٱدۡعُوهُ خَوۡفٗا وَطَمَعًاۚ إِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ ٥٦\nاعلم أن الخوف على ثلاث درجات؛ الأولى: أن يكون ضعيفًا يخطر على القلب ولا يؤثر في الباطن ولا في الظاهر؛ فوجود هذا كالعدم، والثانية: أن يكون قويًّا فيوقظ العبد من الغفلة ويحمله على الاستقامة، والثالثة: أن يشتد حتى يبلغ إلى القنوط واليأس؛ وهذا لا يجوز. وخير الأمور أوسطها. والناس في الخوف على ثلاث مقامات: فخوف العامة من الذنوب، وخوف الخاصة من الخاتمة، وخوف خاصة الخاصة من السابقة؛ فإن الخاتمة مبنية عليها. ابن جزي:١/٣٦٠.\nما الخوف الذي ينبغي أن تعبد الله به في هذه الآية؟ ووضح معنى السابقة في علم الله وقَدَرِهِ.\nوَٱدۡعُوهُ خَوۡفٗا وَطَمَعًاۚ إِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ ٥٦\nوالرجاء على ثلاث درجات؛ الأولى: رجاء رحمة الله مع التسبب فيها بفعل طاعة وترك معصية؛ فهذا هو الرجاء المحمود، والثانية: الرجاء مع التفريط والعصيان؛ فهذا غرور، والثالثة: أن يَقْوَى الرجاء حتى يبلغ الأمن؛ فهذا حرام. والناس في الرجاء على [ثلاثة] مقامات: فمقام العامة رجاء ثواب الله، ومقام الخاصة رضوان الله، ومقام خاصة الخاصة رجاء لقاء الله حبًّا فيه وشوقًا إليه. ابن جزي: ١/٣٦٠.\nما الرجاء الذي ينبغي أن تعبد الله به في هذه الآية؟\nإِنَّ رَحۡمَتَ ٱللَّهِ قَرِيبٞ مِّنَ ٱلۡمُحۡسِنِينَ ٥٦\nاختص أهل الإحسان بقرب الرحمة لأنها إحسان من الله -عز وجل- أرحم الراحمين، وإحسانه -تبارك وتعالى- إنَّما يكون لأهل الإحسان؛ لأن الجزاء من جنس العمل، وكلّما أحسنوا بأعمالهم أحسن إليهم برحمته. ابن تيمية:١٥/٢٧.\nلماذا اختص أهل الإحسان بقرب الرحمة؟"],[158,"§الأعراف\nwords\nنَكِدًاعَسِرًا، رَدِيئًا.\nنُصَرِّفُنُنَوِّعُ.\nعَمِينَعُميَ القُلُوبِ عَن رُؤيَةِ الحَقِّ.\nسَفَاهَةٍخِفَّةِ عَقلٍ.\ndeeds\nاشكر الله تعالى بقلبك ولسانك وعملك، وأكثر من ذلك؛ فإن شكر النعم من أسبابِ حصول العلم والفهم، وزيادة الإيمان.\nسل الله تعالى أن ينَجِّي المستضعفين الموحدين، وأن يهلك الظالمين الطغاة المعتدين.\nاقرأ عن مسائل تحتاجها في التوحيد، وذكر بها من حولك.\nguid\nاتفقت دعوة الأنبياء على التوحيد، فاحرص على هذا الأصل العظيم تعلمًا وتعليمًا وتطبيقًا.\nالضالون من أصحاب المنافع والنفوذ هم أكثر من يرد دعوه الحق؛ لمنافاتها شهواتهم.\nصفتان ما تحلى بهما داعية إلا أوتي البركة والقبول: النصيحة الصادقة، والعلم؛ فاجتهد في تربية نفسك عليهما.\nrefl\nوَٱلۡبَلَدُ ٱلطَّيِّبُ يَخۡرُجُ نَبَاتُهُۥ بِإِذۡنِ رَبِّهِۦۖ وَٱلَّذِي خَبُثَ لَا يَخۡرُجُ إِلَّا نَكِدٗاۚ كَذَٰلِكَ نُصَرِّفُ ٱلۡأٓيَٰتِ لِقَوۡمٖ يَشۡكُرُونَ ٥٨\nهذا مثال للقلوب حين ينزل عليها الوحي... فإن القلوب الطيبة حين يجيئها الوحي تقبله، وتعلمه، وتنبت بحسب طيب أصلها، وحسن عنصرها، وأمَّا القلوب الخبيثة التي لا خير فيها، فإذا جاءها الوحي لم يجد محلًّا قابلًا، بل يجدها غافلة معرضة، أو معارضة، فيكون كالمطر الذي يمر على السباخ والرمال والصخور، فلا يؤثر فيها شيئًا. السعدي:٢٩٢.\nما أنواع القلوب في تقبلها للوحي؟\nقَالَ ٱلۡمَلَأُ مِن قَوۡمِهِۦٓ إِنَّا لَنَرَىٰكَ فِي ضَلَٰلٖ مُّبِينٖ ٦٠\n﴿قَالَ ٱلۡمَلَأُ مِن قَوۡمِهِۦٓ﴾ أي: الجمهور، والسادة، والقادة، والكبراء منهم. (إنا لنراك في ضلال مبين) أي: في دعوتك إيانا إلى ترك عبادة هذه الأصنام التي وجدنا عليها آباءنا. وهكذا حال الفجار: إنَّما يرون الأبرار في ضلالة؛ كما قال تعالى: ﴿وَإِذَا رَأَوۡهُمۡ قَالُوٓاْ إِنَّ هَٰٓؤُلَآءِ لَضَآلُّونَ﴾ [المطففين: ٣٢]، ﴿وَقَال ٱلَّذِينَ كَفَرُواْ لِلَّذِينَ ءَامَنُواْ لَوۡ كَانَ خَيۡرٗا مَّا سَبَقُونَآ إِلَيۡهِ﴾ [الأحقاف: ١١]. ابن كثير:٢/٢١٤.\nبيّن بعض ابتلاءات الصالحين من خلال الآية.\nقَالَ يَٰقَوۡمِ لَيۡسَ بِي ضَلَٰلَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ٦١\nوقوله لهم جوابًا عن هذا: ﴿لَيۡسَ بِي ضَلَٰلَةٌ﴾ مبالغة في حسن الأدب، والإعراض عن الجفاء منهم، وتناول رفيق، وسعة صدر حسبما يقتضيه خلق النبوة. ابن عطية:٢/٤١٥.\nفي جواب نوح -عليه السلام- لقومه منهج للدعاة، بيّنه.\nقَالَ يَٰقَوۡمِ لَيۡسَ بِي ضَلَٰلَةٞ وَلَٰكِنِّي رَسُولٞ مِّن رَّبِّ ٱلۡعَٰلَمِينَ ٦١\nوهذا شأن الرسول، أن يكون مبلغًا، فصيحًا، ناصحًا، عالمًا بالله. ابن كثير:٢/٢١٤.\nما الصفات التي ينبغي أن يكون عليها الداعية إلى الله -سبحانه وتعالى-؟\nأُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنصَحُ لَكُمۡ وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ ٦٢\nأي: وظيفتي تبليغكم ببيان توحيده وأوامره ونواهيه، على وجه النصيحة لكم والشفقة عليكم، ﴿وَأَعۡلَمُ مِنَ ٱللَّهِ مَا لَا تَعۡلَمُونَ﴾ فالذي يتعين أن تطيعوني وتنقادوا لأمري إن كنتم تعلمون. السعدي:٢٩٣.\nإذا كان الرسول يعلم من الله ما لا يعلمه الناس، فما الذي يستوجبه ذلك على الناس؟\nفَكَذَّبُوهُ فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِي ٱلۡفُلۡكِ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ إِنَّهُمۡ كَانُواْ قَوۡمًا عَمِينَ ٦٤\nفقدم الإنجاء للاهتمام بإنجاء المؤمنين، وتعجيلًا لمسرة السامعين من المؤمنين بأن عادة الله إذا أهلك المشركين أن ينجي الرسول والمؤمنين. ابن عاشور:٨/١٩٧.\nلماذا قدم الإنجاء للمؤمنين على الإغراق للكافرين في الآية الكريمة؟\nفَكَذَّبُوهُ فَأَنجَيۡنَٰهُ وَٱلَّذِينَ مَعَهُۥ فِي ٱلۡفُلۡكِ وَأَغۡرَقۡنَا ٱلَّذِينَ كَذَّبُواْ بِـَٔايَٰتِنَآۚ\nوهذه سنة الله في عباده في الدنيا والآخرة: أن العاقبة فيها للمتقين، والظفر والغلب لهم؛ كما أهلك قوم نوح بالغرق، ونجى نوحًا وأصحابه المؤمنين. ابن كثير:٢/٢١٤.\nفي قصة نوح -عليه السلام- فائدة يفيدها المسلمون المضطهدون، فما هي؟"],[159,"§الأعراف\nwords\nبَسطَةًقُوَّةً، وَضَخَامَةً.\nآلاَءَ اللهِنِعَمَ اللهِ.\nرِجسٌعَذَابٌ.\nوَقَطَعنَا دَابِرَأَهلَكنَاهُم جَمِيعًا.\ndeeds\nبلغ اليوم، وبأسلوب حسن، دعوة الله -عز وجل- تجاه منكر أو فساد رأيتـه.\nاجلس مع نفسك ساعة تتذكر فيها آلاء الله تعالى عليك، وعظيم نعمائه.\nسل الله تعالى أن ينجي المؤمنين المستضعفين في زماننا برحمته، وأن يقطع دابر أعداء الدين بقدرته.\nguid\nاحتجاج المشركين على صحَّة باطلهم بفعل آبائهم وأجدادهم يكاد يكون سنّةً مطَّردةً في أهل الباطل، وهو من التقليد المذموم.\nمن جهل المشركين استعجالهم العذاب، ومطالبتهم به.\nكل حكم أو قول ليس عليه دليل فهو باطل.\nrefl\nأُبَلِّغُكُمۡ رِسَٰلَٰتِ رَبِّي وَأَنَا۠ لَكُمۡ نَاصِحٌ أَمِينٌ ٦٨\nوهذه الصفات التي يتصف بها الرسل: البلاغ، والنصح، والأمانة. ابن كثير:٢/٢١٥.\nما الصفات التي يجب أن يتحلى بها الداعية في دعوته؟\nوَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةٗۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ ٦٩\nانتقل من أمرهم بالتوحيد إلى تذكيرهم بنعمة الله عليهم التي لا ينكرون أنها من نعم الله دون غيره؛ لأن الخلق والأمر لله لا لغيره؛ تذكيرًا من شأنه إيصالهم إلى إفراد الله تعالى بالعبادة. ابن عاشور:٨/٢٠٤.\nلماذا جاء التذكير بالنعم بعد الأمر بالتوحيد؟\nوَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ وَزَادَكُمۡ فِي ٱلۡخَلۡقِ بَصۜۡطَةٗۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ لَعَلَّكُمۡ تُفۡلِحُونَ ٦٩\nوهذا التذكير تصريح بالنعمة، وتعريض بالنذارة والوعيد بأن قوم نوح إنَّما استأصلهم وأبادهم عذاب من الله على شركهم، فمن اتبعهم في صنعهم يوشك أن يحل به عذاب أيضًا. ابن عاشور:٨/٢٠٥.\nهل يمكن أن يعاقب مجتمع بأكمله؟ وضح ذلك من خلال الآية.\nوَٱذۡكُرُوٓاْ إِذۡ جَعَلَكُمۡ خُلَفَآءَ مِنۢ بَعۡدِ قَوۡمِ نُوحٖ\nوجعلكم تخلفون الأمم الهالكة الذين كذبوا الرسل، فأهلكهم الله وأبقاكم؛ لينظر كيف تعملون، واحذروا أن تقيموا على التكذيب كما أقاموا فيصيبكم ما أصابهم. السعدي:٢٩٤.\nلماذا ذكر هودٌ قومَ نوحٍ لقومه؟\nقَالُوٓاْ أَجِئۡتَنَا لِنَعۡبُدَ ٱللَّهَ وَحۡدَهُۥ وَنَذَرَ مَا كَانَ يَعۡبُدُ ءَابَآؤُنَا فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ ٧٠\nقبحهم الله؛ جعلوا الأمر الذي هو أوجب الواجبات وأكمل الأمور، من الأمور التي لا يعارضون بها ما وجدوا عليه آباءهم، فقدموا ما عليه الآباء الضالون من الشرك وعبادة الأصنام على ما دعت إليه الرسل من توحيد الله وحده لا شريك له، وكذبوا نبيهم، وقالوا: ﴿فَأۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلصَّٰدِقِينَ﴾. السعدي:٢٩٤.\nما موقف المؤمن إذا تعارضت مفاهيم قومه وعاداتهم مع شرع الله سبحانه؟\nقَالَ قَدۡ وَقَعَ عَلَيۡكُم مِّن رَّبِّكُمۡ رِجۡسٞ وَغَضَبٌۖ أَتُجَٰدِلُونَنِي فِيٓ أَسۡمَآءٖ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم مَّا نَزَّلَ ٱللَّهُ بِهَا مِن سُلۡطَٰنٖۚ\n﴿قَدۡ وَقَعَ عَلَيۡكُم مِّن رَّبِّكُمۡ رِجۡسٌ وَغَضَبٌۖ﴾ أي: لا بد من وقوعه؛ فإنه قد انعقدت أسبابه، وحان وقت الهلاك. ﴿أَتُجَٰدِلُونَنِي فِيٓ أَسۡمَآءٍ سَمَّيۡتُمُوهَآ أَنتُمۡ وَءَابَآؤُكُم﴾ أي: كيف تجادلون على أمور لا حقائق لها، وعلى أصنام سميتموها آلهة وهي لا شيء من [الإلهية] فيها، ولا مثقال ذرة. السعدي:٢٩٤.\nكيف يقول هودٌ بأنه قد وقع عليهم العذاب وهو لم يقع بعد؟\nقَدۡ جَآءَتۡكُم بَيِّنَةٞ مِّن رَّبِّكُمۡۖ هَٰذِهِۦ نَاقَةُ ٱللَّهِ لَكُمۡ ءَايَةٗۖ فَذَرُوهَا تَأۡكُلۡ فِيٓ أَرۡضِ ٱللَّهِۖ وَلَا تَمَسُّوهَا بِسُوٓءٖ فَيَأۡخُذَكُمۡ عَذَابٌ أَلِيمٞ ٧٣\n﴿بَيِّنَةٌ مِّن رَّبِّكُمۡ﴾ أي: آية ظاهرة؛ وهي الناقة، وأضيفت إلى الله تشريفًا لها، أو لأنه خلقها من غير فحل، وكانوا قد اقترحوا على صالح -عليه السلام- أن يخرجها لهم من صخرة، وعاهدوه أن يؤمنوا به إن فعل ذلك؛ فانشقت الصخرة وخرجت منها الناقة وهم ينظرون، ثم نتجت ولدًا فآمن به قوم منهم، وكفر به آخرون. ابن جزي:١/٣٦٠.\nمن لم يكتب الله له الهداية فإنه لا يريد من النقاش والحوار إلا التعجيز، وضح ذلك من الآية."],[160,"§الأعراف\nwords\nوَبَوَّأَكُمأَسكَنَكُم وَمَكَّنَ لَكُم.\nوَلاَ تَعثَوالاَ تَسعَوا.\nفَعَقَرُوافَقَتَلُوا.\nوَعَتَوااستَكبَرُوا.\nالرَّجفَةُالزَّلزَلَةُ الشَّدِيدَةُ.\ndeeds\nقل: \"اللهم حبب إليَّ الإيمان وزينه في قلبي، وكرِّه إليَّ الكفر والفسوق والعصيان، واجعلني من الراشدين\".\nأرسل رسالة عن الكبر، وأنه من أسباب الشرك والكفر.\nتذكر شخصًا نصحك واشكره وادعُ له.\nguid\nالنعم تزول بالمعاصي فابتعد عنها.\nتعلم ممن هم أقل منك حالًا، ولا تترفع عن قبول الحق ممن هو دونك.\nمن علامات قرب الهلاك كره الناس للنصح والناصحين إذا خالفوا هوى أنفسهم.\nrefl\nوَبَوَّأَكُمۡ فِي ٱلۡأَرۡضِ تَتَّخِذُونَ مِن سُهُولِهَا قُصُورٗا وَتَنۡحِتُونَ ٱلۡجِبَالَ بُيُوتٗاۖ فَٱذۡكُرُوٓاْ ءَالَآءَ ٱللَّهِ وَلَا تَعۡثَوۡاْ فِي ٱلۡأَرۡضِ مُفۡسِدِينَ ٧٤\nأي: لا تخربوا الأرض بالفساد والمعاصي؛ فإن المعاصي تدع الديار العامرة بلاقع، وقد أخلت ديارهم منهم، وأبقت مساكنهم موحشة بعدهم. السعدي:٢٩٥.\nما الذي تفعله المعاصي في النعم؟\nقَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لِلَّذِينَ ٱسۡتُضۡعِفُواْ لِمَنۡ ءَامَنَ مِنۡهُمۡ أَتَعۡلَمُونَ أَنَّ صَٰلِحٗا مُّرۡسَلٞ مِّن رَّبِّهِۦۚ قَالُوٓاْ إِنَّا بِمَآ أُرۡسِلَ بِهِۦ مُؤۡمِنُونَ ٧٥\nعدل الملأ الذين استكبروا عن مجادلة صالح -عليه السلام- إلى اختبار تصلب الذين آمنوا به في إيمانهم، ومحاولة إلقاء الشك في نفوسهم. ولما كان خطابهم للمؤمنين مقصودًا به إفساد دعوة صالح -عليه السلام- كان خطابهم بمنزلة المحاورة مع صالح -عليه السلام-... ووصفهم بالذين استكبروا هنا لتفظيع كبرهم، وتعاظمهم على عامة قومهم، واستذلالهم إياهم، وللتنبيه على أن الذين آمنوا بما جاءهم به صالح -عليه السلام- هم ضعفاء قومه. ابن عاشور:٨/٢٢٢.\nبيّن من خلال الآية تنوع أساليب قوم صالح -عليه السلام- في الصد عن دعوته.\nقَالَ ٱلَّذِينَ ٱسۡتَكۡبَرُوٓاْ إِنَّا بِٱلَّذِيٓ ءَامَنتُم بِهِۦ كَٰفِرُونَ ٧٦\nحملهم الكبر أن لا ينقادوا للحق الذي انقاد له الضعفاء. السعدي:٢٩٥.\nبيِّن من خلال الآية ضررًا من أضرار الكبر.\nفَعَقَرُواْ ٱلنَّاقَةَ وَعَتَوۡاْ عَنۡ أَمۡرِ رَبِّهِمۡ وَقَالُواْ يَٰصَٰلِحُ ٱئۡتِنَا بِمَا تَعِدُنَآ إِن كُنتَ مِنَ ٱلۡمُرۡسَلِينَ ٧٧\n﴿فَعَقَرُواْ ٱلنَّاقَةَ﴾: نسب العقر إلى جميعهم؛ لأنهم رضوا به، وإن لم يفعله إلا واحد منهم. ابن جزي:١/٣٦٠.\nما وجه نسبة العقر إلى جميع القبيلة مع أن العاقر واحد؟\nفَتَوَلَّىٰ عَنۡهُمۡ وَقَالَ يَٰقَوۡمِ لَقَدۡ أَبۡلَغۡتُكُمۡ رِسَالَةَ رَبِّي وَنَصَحۡتُ لَكُمۡ وَلَٰكِن لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ ٧٩\nقوله: ﴿لَّا تُحِبُّونَ ٱلنَّٰصِحِينَ﴾ عبارة عن تغليبهم الشهوات على الرأي؛ إذ كلام الناصح صعب مضاد لشهوة نفس الذي يُنصح. ابن عطية:٢/٤٢٤.\nلماذا غالب الناس لا يحبون من ينصحهم؟\nوَلُوطًا إِذۡ قَالَ لِقَوۡمِهِۦٓ أَتَأۡتُونَ ٱلۡفَٰحِشَةَ مَا سَبَقَكُم بِهَا مِنۡ أَحَدٖ مِّنَ ٱلۡعَٰلَمِينَ ٨٠\n﴿أَتَأۡتُونَ ٱلۡفَٰحِشَةَ﴾ أي: الخصلة التي بلغت في العظم والشناعة إلى أن استغرقت أنواع الفحش، ﴿مَا سَبَقَكُم بِهَا مِنۡ أَحَدٍ مِّنَ ٱلۡعَٰلَمِينَ﴾: فكونها فاحشة من أشنع الأشياء، وكونهم ابتدعوها وابتكروها وسنوها لمن بعدهم من أشنع ما يكون أيضًا. السعدي:٢٩٦.\nمتى يتضاعف إثم المعصية؟ بيِّن ذلك من خلال الآية.\nإِنَّكُمۡ لَتَأۡتُونَ ٱلرِّجَالَ شَهۡوَةٗ مِّن دُونِ ٱلنِّسَآءِۚ بَلۡ أَنتُمۡ قَوۡمٞ مُّسۡرِفُونَ ٨١\nأي أنتم قوم تمكن منهم الإسراف في الشهوات؛ فلذلك اشتهوا شهوة غريبة لمَّا سئموا الشهوات المعتادة. ابن عاشور:٨/٢٣٢.\nلماذا وصف قوم لوط بأنهم ﴿قَوۡمٌ مُّسۡرِفُونَ﴾؟"],[161,"§الأعراف\nwords\nالغَابِرِينَالهَالِكِينَ، البَاقِينَ فِي العَذَابِ.\nوَلاَ تَبخَسُوالاَ تَنقُصُوا.\nتُوعِدُونَتَتَوَعَّدُونَ النَّاسَ بِالقَتلِ.\nوَتَبغُونَهَا عِوَجًاتُرِيدُونَهَا مُعوَجَّةً، وَتُمِيلُونَهَا اتِّبَاعًا لأِهوَائِكُم.\ndeeds\nاقرأ قصة شعيب، واكتب ثلاثًا مما اشتملت عليها من فوائد.\nذكّر بعض البائعين بما تراه مناسبًا من الوسائل، بأهمية العدل في الميزان.\nانصح من يجلس في الشوارع لإيذاء الناس.\nguid\nمن عادة المجرمين والفاسقين أنهم يقلبون الحقائق؛ فيَذُمُّون الصالحين، ويمدحون المفسدين.\nدين الله تعالى ليس فيه محاباة لأحد؛ فإن امرأة لوط لمَّا عصت جعلها الله من المعذبين.\nالتأمل في عاقبة المفسدين سببٌ رادع وزاجر لمن يفكر بالمعصية.\nrefl\nوَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوهُم مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ ٨٢\nوقولهم: ﴿إِنَّهُمۡ أُنَاسٌ يَتَطَهَّرُونَ﴾ سخرية بهم، وبتطهرهم من الفواحش، وافتخار بما كانوا فيه من القذارة؛ كما يقول الشطار من الفسقة لبعض الصلحاء إذا وعظهم: أبعدوا عنا هذا المتقشف، وأريحونا من هذا المتزهد. القاسمي:٥/١٣٩.\nما علامة انقلاب الموازين عند بعض العقول؟\nوَمَا كَانَ جَوَابَ قَوۡمِهِۦٓ إِلَّآ أَن قَالُوٓاْ أَخۡرِجُوهُم مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٞ يَتَطَهَّرُونَ ٨٢\nقال الإمام شمس الدين ابن القيم: \"وقول اللوطية: ﴿أَخۡرِجُوهُم مِّن قَرۡيَتِكُمۡۖ إِنَّهُمۡ أُنَاسٌ يَتَطَهَّرُونَ﴾ من جنس قوله سبحانه في أصحاب الأخدود: ﴿وَمَا نَقَمُواْ مِنۡهُمۡ إِلَّآ أَن يُؤۡمِنُواْ بِٱللَّهِ ٱلۡعَزِيزِ ٱلۡحَمِيدِ﴾ [البروج: ٨]، وهكذا المشرك؛ إنَّما ينقم على الموحد تجريده للتوحيد وأنه لا يشوبه بالإشراك، وهكذا المبتدع؛ إنَّما ينقم على السنيّ تجريده متابعة الرسول، وأنه لم يَشُبْها بآراء الرجال، ولا بشيء مما خالفها. فصبر الموحد المتبع للرسول على ما ينقمه عليه أهل الشرك والبدعة خير له وأنفع، وأسهل عليه من صبره على ما ينقمه الله ورسوله من موافقة أهل الشرك والبدعة\". القاسمي: ٥/١٤١.\nكيف يواجه المؤمن استهزاء المستهزئين؟\nفَأَوۡفُواْ ٱلۡكَيۡلَ وَٱلۡمِيزَانَ وَلَا تَبۡخَسُواْ ٱلنَّاسَ أَشۡيَآءَهُمۡ\nالبخس: النقص، وهو يكون في السلعة بالتعييب، والتزهيد فيها، أو المخادعة عن القيمة، والاحتيال في التزيد في الكيل، والنقصان منه، وكل ذلك من أكل المال بالباطل، وذلك منهي عنه في الأمم المتقدمة والسالفة على ألسنة الرسل -صلوات الله وسلامه على جميعهم-. القرطبي:١٠/٣٣٣.\nكيف يكون البخس في السلع؟\nوَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ بَعۡدَ إِصۡلَٰحِهَاۚ ذَٰلِكُمۡ خَيۡرٞ لَّكُمۡ إِن كُنتُم مُّؤۡمِنِينَ ٨٥\n﴿وَلَا تُفۡسِدُواْ فِي ٱلۡأَرۡضِ﴾ أي: بالكفر والظلم، ﴿بَعۡدَ إِصۡلَٰحِهَا﴾ أي: بعد ما أصلح أمرها وأهلها الأنبياء وأتباعهم الصالحون العاملون بشرائعهم من وضع الكيل والوزن، والحدود والأحكام. القاسمي:٥/١٤٧.\nما أشدُّ أنواع الإفساد في الأرض؟\nوَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٖ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ و\nعن ابن عباس قوله: ﴿وَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٍ تُوعِدُونَ﴾: والصراط: الطريق؛ يخوِّفون الناس أن يأتوا شعيبًا...قال: \"كانوا يجلسون في الطريق، فيخبرون مَن أتى عليهم أن شعيبًا -عليه السلام- كذّاب، فلا يفتنكم عن دينكم\". الطبري:١٢/٥٥٧.\nهناك تشابه في طرق تشويه سمعة الدعاة والصد عنهم قديمًا وحديثًا، وضح ذلك.\nوَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٖ تُوعِدُونَ وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ وَتَبۡغُونَهَا عِوَجٗاۚ\nينهاهم شعيب -عليه السلام- عن قطع الطريق الحسي والمعنوي بقـوله: ﴿وَلَا تَقۡعُدُواْ بِكُلِّ صِرَٰطٍ تُوعِدُونَ﴾ أي: تتوعدون الناس بالقتل إن لم يعطوكم أموالهم... ﴿وَتَصُدُّونَ عَن سَبِيلِ ٱللَّهِ مَنۡ ءَامَنَ بِهِۦ وَتَبۡغُونَهَا عِوَجًاۚ﴾ أي: وتودون أن تكون سبيل الله عوجًا مائلةً. ابن كثير:٢/٢٢٢.\nقطع الطريق نوعان، فما هما؟\nوَٱذۡكُرُوٓاْ إِذۡ كُنتُمۡ قَلِيلٗا فَكَثَّرَكُمۡۖ\nأي: نَمَّاكم بما أنعم عليكم من الزوجات والنسل والصحة، وأنه ما ابتلاكم بوباء من أمراض من الأمراض المُقَلِّلَة لكم، ولا سَلَّط عليكم عدوًا يجتاحكم، ولا فَرَّقَكم في الأرض، بل أنعم عليكم؛ باجتماعكم، وإدرار الأرزاق، وكثرة النسل. السعدي:٢٩٦.\nفي الآية إشارة إلى عدة نِعَم، وضِّحها."],[162,"§الأعراف\nwords\nالرَّجفَةُالزَّلزَلَةُ الشَّدِيدَةُ.\nجَاثِمِينَهَالِكِينَ، لاَصِقِينَ بِالأَرضِ عَلَى رُكَبِهِم، وَوُجُوهِهِم.\nآسَىأَحزَنُ.\ndeeds\nأرسل رسالة، أو ذكِّر من حولك ببعض المصائب التي حلت بالمجتمع، وأنها لن ترفع إلا بالتوبة والتضرع إلى الله تعالى.\nقل: \"اللهم يا مقلب القلوب ثبت قلبي على دينك\".\nاشكر الله تعالى على نعمه التي أعطاك إياها، ثم توجه إليه بالدعاء ألا تطغيك أو تشغلك هذه النعم عن طاعته.\nguid\nأسلوب المتكبرين واحد؛ وهو: الجدال بالباطل، فإن عجزوا لجؤوا إلى التهديد.\nالمتكبر والغافل إذا تعارضت شهوتهما مع الدين فإنهما يقدمان شهوتهما ومعصيتهما عليه.\nلا يغتر الإنسان بإيمانه وصلاحه؛ فإن الأنبياء والصالحين علموا أن ثباتهم على الدين إنَّما هو بمشيئة الله، لا من عند أنفسهم.\nrefl\nقَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ\nوهم الأشراف والكبراء منهم؛ الذين اتبعوا أهواءهم، ولَهَوا بلذاتهم، فلما أتاهم الحق ورأوه غير موافق لأهوائهم الرديئة ردوه، واستكبروا عنه. السعدي:٢٩٦.\nكيف يؤدي الاغترار بالنعمة إلى الكفر؟\nقَالَ ٱلۡمَلَأُ ٱلَّذِينَ ٱسۡتَكۡبَرُواْ مِن قَوۡمِهِۦ لَنُخۡرِجَنَّكَ يَٰشُعَيۡبُ وَٱلَّذِينَ ءَامَنُواْ مَعَكَ مِن قَرۡيَتِنَآ أَوۡ لَتَعُودُنَّ فِي مِلَّتِنَاۚ قَالَ أَوَلَوۡ كُنَّا كَٰرِهِينَ ٨٨\nإن التزام الدين عن إكراه لا يأتي بالغرض المطلوب من التدين؛ وهو تزكية النفس، وتكثير جند الحق، والصلاح المطلوب. ابن عاشور:٩/٧.\nالتدين عن إكراه لا يأتي بثماره المرجوة، بين ذلك من الآية.\nفَأَخَذَتۡهُمُ ٱلرَّجۡفَةُ\nأخبر تعالى أنهم أخذتهم الرجفة؛ وذلك كما أرجفوا شعيبًا وأصحابه، وتوعدوهم بالجلاء. ابن كثير:٢/٢٢٣.\nما المناسبة بين عذاب مدين بالرجفة وموقفهم من شعيب -عليه السلام-؟\nٱلَّذِينَ كَذَّبُواْ شُعَيۡبٗا كَأَن لَّمۡ يَغۡنَوۡاْ فِيهَاۚ\nأي: كأنهم لمَّا أصابتهم النقمة لم يقيموا بديارهم التي أرادوا إجلاء الرسول وصحبه منها. ابن كثير:٢/٢٢٣.\nفي ضوء هذه الآية: تحدث عن قاعدة (الجزاء من جنس العمل).\nفَكَيۡفَ ءَاسَىٰ عَلَىٰ قَوۡمٖ كَٰفِرِينَ ٩٣\nأي: أحزن. القرطبي:٩/٢٨٧.\nهل من شأن المؤمن أن يحزن لهلاك الكفار؟\nوَمَآ أَرۡسَلۡنَا فِي قَرۡيَةٖ مِّن نَّبِيٍّ إِلَّآ أَخَذۡنَآ أَهۡلَهَا بِٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ لَعَلَّهُمۡ يَضَّرَّعُونَ ٩٤\nوتخصيص القرى بإرسال الرسل فيها دون البوادي -كما أشارت إليه هذه الآية وغيرها من آي القرآن، وشهد به تاريخ الأديان- يُنبئ أن مراد الله تعالى من إرسال الرسل هو بث الصلاح لأصحاب الحضارة التي يتطرق إليها الخلل بسبب اجتماع الأصناف المختلفة، وأن أهل البوادي لا يخلون عن الانحياز إلى القرى والإيواء في حاجاتهم المدنية إلى القرى القريبة. ابن عاشور:٩/١٦.\nبيّن حكمة الله تعالى في إرسال الرسل إلى أهل القرى دون أهل البوادي.\nثُمَّ بَدَّلۡنَا مَكَانَ ٱلسَّيِّئَةِ ٱلۡحَسَنَةَ حَتَّىٰ عَفَواْ وَّقَالُواْ قَدۡ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ فَأَخَذۡنَٰهُم بَغۡتَةٗ وَهُمۡ لَا يَشۡعُرُونَ ٩٥\n﴿ثُمَّ بَدَّلۡنَا مَكَانَ ٱلسَّيِّئَةِ ٱلۡحَسَنَةَ﴾ أي: أبدلنا البأساء والضراء بالنعيم؛ اختبارًا لهم في الحالتين، ﴿حَتَّىٰ عَفَواْ﴾ أي: كثروا ونموا في أنفسهم وأموالهم، ﴿وَّقَالُواْ قَدۡ مَسَّ ءَابَآءَنَا ٱلضَّرَّآءُ وَٱلسَّرَّآءُ﴾ أي: قد جرى ذلك لآبائنا، ولم يضرهم، فهو بالاتفاق لا بقصد الاختبار. ابن جزي:١/٣٦٠.\nما سبب عدم الاتعاظ باختبار الله للناس بالخير والشر؟ وهل ينطبق هذا على بعض المظاهر في زماننا؟"],[163,"§الأعراف\nwords\nبَأسُنَاعَذَابُنَا.\nبَيَاتًالَيلًا.\nأَوَلَم يَهدِأَوَلَم يَتَبَيَّن.\nيَرِثُونَيَسكُنُونَ.\nوَنَطبَعُنَختِمُ.\ndeeds\nألق كلمة، أو أرسل رسالة تبيّن فيها أن حل مشاكل المجتمع إنَّما هو بالتعاون على الإيمان بوعد الله ووعيده، وباتقاء المعاصي.\nاختر قرية أو قبيلة ذُكرت قصتها في القرآن، واجمع قصتها من كامل القرآن لتتدبرها.\nحافظ على الصلاة مع الجماعة؛ فهي من العهد الذي بينك وبين الله.\nguid\nإذا أمن المجتمع مكر الله فقد تهيأ للخسران واقترب منه.\nما يصيبك من بلاء ومحنة فهو بسبب ذنوبك وتقصيرك.\nمن أعظم المصائب أن يطبع على القلب؛ فلا يعي خيرًا، ولا يكُفَّ عن شرٍّ.\nrefl\nوَلَوۡ أَنَّ أَهۡلَ ٱلۡقُرَىٰٓ ءَامَنُواْ وَٱتَّقَوۡاْ لَفَتَحۡنَا عَلَيۡهِم بَرَكَٰتٖ مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ وَلَٰكِن كَذَّبُواْ فَأَخَذۡنَٰهُم بِمَا كَانُواْ يَكۡسِبُونَ ٩٦\nوقوله: ﴿بَرَكَٰتٍ مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ﴾ مراد به حقيقته؛ لأن ما يناله الناس من الخيرات الدنيوية لا يعدو أن يكون ناشئًا من الأرض؛ وذلك معظم المنافع، أو من السماء؛ مثل ماء المطر، وشعاع الشمس، وضوء القمر، والنجوم، والهواء والرياح الصالحة. ابن عاشور:٩/٢٢.\nالبركات التي تحل بالناس إما أن تكون من السماء أو الأرض، بين ذلك.\nوَلَوۡ أَنَّ أَهۡلَ ٱلۡقُرَىٰٓ ءَامَنُواْ وَٱتَّقَوۡاْ لَفَتَحۡنَا عَلَيۡهِم بَرَكَٰتٖ مِّنَ ٱلسَّمَآءِ وَٱلۡأَرۡضِ\nأهل القرى لو آمنوا بقلوبهم إيمانًا صادقًا صدقته الأعمال، واستعملوا تقوى الله تعالى ظاهرًا وباطنًا بترك جميع ما حرَّم الله؛ لفتح عليهم بركات السماء والأرض. السعدي:٢٩٨.\nكيف تصلح أحوال القرى والمدن؟\nأَفَأَمِنُواْ مَكۡرَ ٱللَّهِۚ فَلَا يَأۡمَنُ مَكۡرَ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡخَٰسِرُونَ ٩٩\nومكر الله واستدراجه إياهم بما أنعم عليهم في دنياهم. البغوي:٢/١٣٢.\nما المراد بمكر الله في الآية؟\nفَلَا يَأۡمَنُ مَكۡرَ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡخَٰسِرُونَ ٩٩\nوهذه الآية الكريمة فيها من التخويف البليغ على أن العبد لا ينبغي له أن يكون آمنًا على ما معه من الإيمان، بل لا يزال خائفًا وجلًا أن يبتلى ببلية تسلب ما معه من الإيمان. السعدي:٢٩٨.\nما الذي ينبغي أن يفعله مُتَدَبِّرُ هذه الآية؟\nفَلَا يَأۡمَنُ مَكۡرَ ٱللَّهِ إِلَّا ٱلۡقَوۡمُ ٱلۡخَٰسِرُونَ ٩٩\nقال الحسن البصري -رحمه الله-: \"المؤمن يعمل بالطاعات وهو مُشفِقٌ وَجِل خائف، والفاجر يعمل بالمعاصي وهو آمن\". ابن كثير:٢/٢٢٤.\nما الفرق بين المؤمن والفاجر في أمنهم من مكر الله؟\nأَوَ لَمۡ يَهۡدِ لِلَّذِينَ يَرِثُونَ ٱلۡأَرۡضَ مِنۢ بَعۡدِ أَهۡلِهَآ أَن لَّوۡ نَشَآءُ أَصَبۡنَٰهُم بِذُنُوبِهِمۡۚ وَنَطۡبَعُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَسۡمَعُونَ ١٠٠\n﴿وَنَطۡبَعُ عَلَىٰ قُلُوبِهِمۡ فَهُمۡ لَا يَسۡمَعُونَ﴾أي: إذا نبههم الله فلم ينتبهوا، وذكرهم فلم يتذكروا، وهداهم بالآيات والعبر فلم يهتدوا؛ فإن الله تعالى يعاقبهم، ويطبع على قلوبهم، فيعلوها الران والدنس، حتى يختم عليها، فلا يدخلها حق، ولا يصل إليها خير، ولا يسمعون ما ينفعهم، وإنَّما يسمعون ما به تقوم الحجة عليهم. السعدي:٢٩٨.\nما أشد العقوبات الدنيوية للمعرضين عن دين الله؟\nفَٱنظُرۡ كَيۡفَ كَانَ عَٰقِبَةُ ٱلۡمُفۡسِدِينَ ١٠٣\nأي: انظر يا محمد كيف فعلنا بهم، وأغرقناهم عن آخرهم بمرأىً من موسى وقومه، وهذا أبلغ في النكال بفرعون وقومه، وأشفى لقلوب أولياء الله موسى وقومه من المؤمنين به. ابن كثير:٢/٢٢٥-٢٢٦.\nما الحكمة من الأمر بالنظر في عاقبة المفسدين؟"],[164,"§الأعراف\nwords\nحَقِيقٌجَدِيرٌ.\nثُعبَانٌ مُبِينٌحَيَّةٌ عَظِيمَةٌ.\nوَنَزَعَ يَدَهُنَزَعَهَا مِن جَيبِهِ، أَو جَنَاحِهِ.\nأَرجِهأَخِّرهُ.\nوَاستَرهَبُوهُمخَوَّفُوهُم، وَأَرهَبُوهُم.\nوَانقَلَبُواانصَرَفُوا.\nصَاغِرِينَأَذِلاَّءَ، مَقهُورِينَ.\ndeeds\nاعمل مشروعًا، أو عملًا قوليًا أو ماليًا، تدافع به عن مظلومين، وتساعد فيه مضطهدين.\nسل الله تعالى أن يستخدمك في طاعته، وأن تكون من أنصار الحق.\nانشر مقطعًا مرئيًا، أو محاضرة تبيّن خطورة السحر.\nguid\nجهل المجتمع بالحق يؤدي إلى سهولة الكذب عليهم.\nمكر الملأ وكذبهم إذ اتهموا موسى بأنه يريد الملك، وهو إنَّما أراد تعبيد الناس لله وحده.\nمهما فشا الباطل وارتفع، واغتر به المتعجلون؛ فإن للحق يومًا يظهر فيه ويعلو.\nrefl\nفَأَلۡقَىٰ عَصَاهُ فَإِذَا هِيَ ثُعۡبَانٞ مُّبِينٞ ١٠٧ وَنَزَعَ يَدَهُۥ فَإِذَا هِيَ بَيۡضَآءُ لِلنَّٰظِرِينَ ١٠٨ قَالَ ٱلۡمَلَأُ مِن قَوۡمِ فِرۡعَوۡنَ إِنَّ هَٰذَا لَسَٰحِرٌ عَلِيمٞ ١٠٩\n(فألقى) موسى (عصاه) في الأرض ﴿فَإِذَا هِيَ ثُعۡبَانٌ مُّبِينٌ﴾ أي: حية ظاهرة تسعى، وهم يشاهدونها. ﴿وَنَزَعَ يَدَهُۥ﴾ من جيبه ﴿فَإِذَا هِيَ بَيۡضَآءُ لِلنَّٰظِرِينَ﴾ من غير سوء؛ فهاتان آيتان كبيرتان دالتان على صحة ما جاء به موسى وصدقه، وأنه رسول رب العالمين، ولكن الذين لا يؤمنون لو جاءتهم كل آية لا يؤمنون حتى يروا العذاب الأليم. السعدي:١/٢٩٩.\nهل تحصل الهداية بمجرد العقل، أم هي منة من الله؟ وضح ذلك من الآيات.\nقَالُوٓاْ أَرۡجِهۡ وَأَخَاهُ وَأَرۡسِلۡ فِي ٱلۡمَدَآئِنِ حَٰشِرِينَ ١١١ يَأۡتُوكَ بِكُلِّ سَٰحِرٍ عَلِيمٖ ١١٢\nوالشأن أن يكون ملأ فرعون عقلاء أهل سياسة، فعلموا أن أمر دعوة موسى لا يكاد يخفى، وأن فرعون إن سجنه أو عاند تحقق الناس أن حُجة موسى غلبت، فصار ذلك ذريعة للشك في دين فرعون؛ فرأوا أن يلاينوا موسى، وطمعوا أن يوجد في سحرة مصر من يدافع آيات موسى، فتكون الحجة عليه ظاهرة للناس. ابن عاشور:٩/٤٤.\nلماذا لم يقترح ملأ فرعون عليه أن يسجن موسى -عليه السلام-؟\nوَجَآءَ ٱلسَّحَرَةُ فِرۡعَوۡنَ قَالُوٓاْ إِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَٰلِبِينَ ١١٣\n(قالوا) لفرعون ﴿إِنَّ لَنَا لَأَجۡرًا﴾ أي: جُعلًا ومالًا. البغوي:٢/١٣٥.\nكيف بينت الآية أن من أهم صفات دعاة الضلال الحرص على الدنيا؟\nوَجَآءَ ٱلسَّحَرَةُ فِرۡعَوۡنَ قَالُوٓاْ إِنَّ لَنَا لَأَجۡرًا إِن كُنَّا نَحۡنُ ٱلۡغَٰلِبِينَ ١١٣ قَالَ نَعَمۡ وَإِنَّكُمۡ لَمِنَ ٱلۡمُقَرَّبِينَ ١١٤\nقال فرعون للسحرة، إذ قالوا له: إن لنا عندك ثوابًا إن نحن غلبنا موسى؟ قال: نعم، لكم ذلك، وإنكم لممن أقرِّبه وأدنيه مني. الطبري:١٣/٢٦.\nفي الآية إشارة لحرص الطغاة على تقريب أئمة الضلال واستشارتهم، وضح ذلك.\nقَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ نَحۡنُ ٱلۡمُلۡقِينَ ١١٥ قَالَ أَلۡقُواْۖ\nقيل: الحكمة في هذا -والله أعلم- ليرى الناس صنيعَهم، ويتأملوه، فإذا فرغوا من بهرجهم ومحالهم؛ جاءهم الحق الواضح الجلي بعد التطلب له، والانتظار منهم لمجيئه، فيكون أوقع في النفوس، وكذا كان. ابن كثير:٢/٢٢٧.\nما الحكمة في تفضيل موسى أن يلقي السحرة عصيهم قبله؟\nقَالُواْ يَٰمُوسَىٰٓ إِمَّآ أَن تُلۡقِيَ وَإِمَّآ أَن نَّكُونَ نَحۡنُ ٱلۡمُلۡقِينَ ١١٥ قَالَ أَلۡقُواْۖ فَلَمَّآ أَلۡقَوۡاْ سَحَرُوٓاْ أَعۡيُنَ ٱلنَّاسِ وَٱسۡتَرۡهَبُوهُمۡ وَجَآءُو بِسِحۡرٍ عَظِيمٖ ١١٦\nتأدبوا مع موسى -عليه السلام- فكان ذلك سبب إيمانهم. القرطبي:٩/٢٩٦.\nمن خلال الآية: بيّن ثمرة الأدب مع العلماء والصالحين.\nوَأُلۡقِيَ ٱلسَّحَرَةُ سَٰجِدِينَ ١٢٠\nوأعظم من تبين له الحق العظيم أهل الصنف والسحر، الذين يعرفون من أنواع السحر وجزئياته ما لا يعرفه غيرهم؛ فعرفوا أن هذه آية عظيمة من آيات الله، لا يَدَان لأحد بها. السعدي:٣٠٠.\nلماذا كان السحرة أسرع الناس إيمانًا في هذه الحادثة؟"],[165,"§الأعراف\nwords\nمُنقَلِبُونَرَاجِعُونَ.\nأَفرِغأَفِض، وَصُبَّ.\nبِالسِّنِينَبِالقَحطِ، وَالجَدبِ.\ndeeds\nكرر هذا الدعاء، وادعُ الله أن يفك أسر المأسورين من المسلمين.\nأرسل رسالة تبين فيها أن خطورة جليس السوء على أهل الحل والعقد أكثر من خطورتها على غيرهم.\nأرسل رسالة إلى أحد المبتلين تحثه فيها على الصبر والثبات، وتبشره بالأجر، وحسن العاقبة.\nguid\nمن أخطر أنواع الكذب على المجتمع كذب الوجهاء.\nالبطانة السيئة شر على البلاد والعباد.\nالعبادة والتقوى شرط لوراثة الأرض.\nrefl\nإِنَّ هَٰذَا لَمَكۡرٞ مَّكَرۡتُمُوهُ فِي ٱلۡمَدِينَةِ\nوموسى-عليه السلام- لا يعرف أحدًا منهم، ولا رآه، ولا اجتمع به، وفرعون يعلم ذلك، وإنَّما قال هذا تستُّرًا وتدليسًا على رعاع دولته وجهلتهم، كما قال تعالى: ﴿فَٱسۡتَخَفَّ قَوۡمَهُۥ فَأَطَاعُوهُ﴾ [الزخرف: ٥٤]؛ فإن قومًا صدّقوه في قوله: ﴿فَقَالَ أَنَا۠ رَبُّكُمُ ٱلۡأَعۡلَىٰ﴾ [النازعات: ٢٤] من أجهل خلق الله وأضلهم. ابن كثير:٢/٢٢٨.\nما مقصد فرعون في قوله: ﴿إِنَّ هَٰذَا لَمَكۡرٌ مَّكَرۡتُمُوهُ فِي ٱلۡمَدِينَةِ﴾؟\nقَالُوٓاْ إِنَّآ إِلَىٰ رَبِّنَا مُنقَلِبُونَ ١٢٥\nوعذابه أشد من عذابك، ونكاله على ما تدعونا إليه اليوم وما أكرهتنا عليه من السحر أعظم من نكالك؛ فلنصبر اليوم على عذابك لنخلص من عذاب الله. ابن كثير:٢/٢٢٨.\nما المقارنة التي دفعت السحرة إلى الإيمان والثبات على دين الله؟\nوَمَا تَنقِمُ مِنَّآ إِلَّآ أَنۡ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا لَمَّا جَآءَتۡنَاۚ\nقال عطاء: \"ما لنا عندك من ذنب تعذبنا عليه ﴿إِلَّآ أَنۡ ءَامَنَّا بِـَٔايَٰتِ رَبِّنَا﴾\". البغوي:٢/١٣٨.\nما الذنب الذي لأجله عادى به المتكبرون أهل الإيمان؟\nرَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا\nأي: عظيمًا، كما يدل عليه التنكير؛ لأن هذه محنة عظيمة تؤدي إلى ذهاب النفس، فيحتاج فيها من الصبر إلى شيء كثير؛ ليثبت الفؤاد، ويطمئن المؤمن على إيمانه، ويزول عنه الانزعاج الكثير. السعدي:٣٠٠.\nلماذا طلب السحرة من الله بعد إيمانهم أن يفرغ عليهم صبرًا؟\nرَبَّنَآ أَفۡرِغۡ عَلَيۡنَا صَبۡرٗا وَتَوَفَّنَا مُسۡلِمِينَ ١٢٦\nاجعل لنا طاقة لتحمُّل ما توعدنا به فرعون، ولما كان ذلك الوعيد مما لا تطيقه النفوس؛ سألوا الله أن يجعل لنفوسهم صبرًا قويًّا، يفوق المتعارف؛... فإن الإفراغ صبُّ جميع ما في الإناء،... ودعوا لأنفسهم بالوفاة على الإسلام إيذانًا بأنهم غير راغبين في الحياة، ولا مبالين بوعيد فرعون، وأن همتهم لا ترجو إلا النجاة في الآخرة، والفوز بما عند الله، وقد انخذل بذلك فرعون، وذهب وعيده باطلًا. ابن عاشور:٩/٥٦.\nإذا حلَّ الإيمان بالقلب كانت الآخرة أهم من الدنيا، وضح ذلك من خلال الآية.\nقَالَ عَسَىٰ رَبُّكُمۡ أَن يُهۡلِكَ عَدُوَّكُمۡ وَيَسۡتَخۡلِفَكُمۡ فِي ٱلۡأَرۡضِ فَيَنظُرَ كَيۡفَ تَعۡمَلُونَ ١٢٩\nوجاء بفعل الرجاء دون الجزم تأدبًا مع الله تعالى، وإقصاء للاتكال على أعمالهم؛ ليزدادوا من التقوى، والتعرض إلى رضى الله تعالى ونصره. ابن عاشور:٩/٦٢.\nلماذا اختار موسى فعل الرجاء (عسى) دون الجزم في الآية الكريمة؟\nوَلَقَدۡ أَخَذۡنَآ ءَالَ فِرۡعَوۡنَ بِٱلسِّنِينَ وَنَقۡصٖ مِّنَ ٱلثَّمَرَٰتِ لَعَلَّهُمۡ يَذَّكَّرُونَ ١٣٠\n(بالسنين) أي: بالجدب والقحط؛ تقول العرب: مسّتهم السَّنَة؛ أي: جدب السنة، وشدة السنة، وقيل: أراد بالسنين: القحط سنة بعد سنة، ﴿وَنَقۡصٍ مِّنَ ٱلثَّمَرَٰتِ﴾ بإتلاف الغلّات بالآفات والعاهات، قال قتادة: \"أما السنين فلأهل البوادي، وأمَّا نقص الثمرات فلأهل الأمصار\"، ﴿لَعَلَّهُمۡ يَذَّكَّرُونَ﴾؛ أي: يتعظون؛ وذلك لأن الشدة ترقق القلوب، وترغبها فيما عند الله -عز وجل-. البغوي، ٢/١٣٩.\nما الحكمة من نزول البلاء والشدة بالعباد؟"],[166,"§الأعراف\nwords\nيَطَّيَّرُوايَتَشَاءَمُوا.\nطَائِرُهُم عِندَ اللَّهِمَا أَصَابَهُم مِنَ القَحطِ بِقَدَرِ اللهِ.\nوَالقُمَّلَحَشَرَةٌ مَعروفَةٌ سُلِّطَت علَيهِم بكثرة فأَفسَدَت الثّمارَ وَقَضَتْ عَلَى الْحَيَوَانِ وَالنَّبَاتِ.\ndeeds\nأرسل رسالة، أو ألق كلمة تحذر فيها المجتمع من معاداة أولياء الله تعالى ودينهم، وقبول الله دعاءهم عليهم.\nتذكر ثلاثة مواضع نصر الله فيها المؤمنين المستضعفين على عدوهم القوي.\nتذكر ثلاث مصائب حديثة حلت بالمجتمع بسبب المجاهرة بالذنوب وترك الأمر بالمعرف والنهي عن المنكر.\nguid\nعلى الإنسان أن يشكر الله تعالى على نِعَمه، ويعلم أنه لا فضل له فيها، بل هي محض فضل الله تعالى.\nمن أكثر ما يضر ابن آدم: المكابرة والمعاندة.\nاحذر الغفلة عن آيات الله تعالى؛ فإنها سبب لنزول العقوبة والعذاب.\nrefl\nفَإِذَا جَآءَتۡهُمُ ٱلۡحَسَنَةُ قَالُواْ لَنَا هَٰذِهِۦۖ\nأي: نحن مستحقون لها، فلم يشكروا الله عليها. السعدي:٣٠١.\nما حال الكفار مع نعم الله -عز وجل-؟\nفَإِذَا جَآءَتۡهُمُ ٱلۡحَسَنَةُ قَالُواْ لَنَا هَٰذِهِۦۖ وَإِن تُصِبۡهُمۡ سَيِّئَةٞ يَطَّيَّرُواْ بِمُوسَىٰ وَمَن مَّعَهُۥٓۗ أَلَآ إِنَّمَا طَٰٓئِرُهُمۡ عِندَ ٱللَّهِ وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ ١٣١\n﴿وَلَٰكِنَّ أَكۡثَرَهُمۡ لَا يَعۡلَمُونَ﴾ أن ما لحقهم من القحط والشدائد إنَّما هو من عند الله -عز وجل- بذنوبهم. القرطبي:٩/٣٠٨.\nهل يدرك أكثر الناس سبب نزول العقوبات والمحن بهم؟\nفَأَرۡسَلۡنَا عَلَيۡهِمُ ٱلطُّوفَانَ وَٱلۡجَرَادَ وَٱلۡقُمَّلَ وَٱلضَّفَادِعَ وَٱلدَّمَ ءَايَٰتٖ مُّفَصَّلَٰتٖ فَٱسۡتَكۡبَرُواْ وَكَانُواْ قَوۡمٗا مُّجۡرِمِينَ ١٣٣\nوسمى الله هاته آيات لأنها دلائل على صدق موسى؛ لاقترانها بالتحدي، ولأنها دلائل على غضب الله عليهم. ابن عاشور:٩/٧٠.\nلماذا سمى الله تعالى الأمور المذكورة في الآية الكريمة آيات؟\nفَٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ فِي ٱلۡيَمِّ بِأَنَّهُمۡ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنۡهَا غَٰفِلِينَ ١٣٦\n﴿وَكَانُواْ عَنۡهَا﴾: ...عن الآيات؛ أي: لم يعتبروا بها حتى صاروا كالغافلين عنها. القرطبي:٩/٣١٥.\nما حقيقة الغفلة؟\nفَٱنتَقَمۡنَا مِنۡهُمۡ فَأَغۡرَقۡنَٰهُمۡ فِي ٱلۡيَمِّ بِأَنَّهُمۡ كَذَّبُواْ بِـَٔايَٰتِنَا وَكَانُواْ عَنۡهَا غَٰفِلِينَ ١٣٦\nأي: أغرقناهم جزاء على تكذيبهم بالآيات، والغفلة: ذهول الذهن عن تذكر شيء... وأريد بها التغافل عن عمد؛ وهو الإعراض عن التفكر في الآيات، وإباية النظر في دلالتها على صدق موسى. ابن عاشور:٩/٧٥.\nما الغفلة التي وقع فيها قوم فرعون؟\nوَأَوۡرَثۡنَا ٱلۡقَوۡمَ ٱلَّذِينَ كَانُواْ يُسۡتَضۡعَفُونَ مَشَٰرِقَ ٱلۡأَرۡضِ وَمَغَٰرِبَهَا ٱلَّتِي بَٰرَكۡنَا فِيهَاۖ\nقد أخبر الله بأنه بارك في أرض الشام في آيات؛ منها قوله: ﴿وَأَوۡرَثۡنَا ٱلۡقَوۡمَ ٱلَّذِينَ كَانُواْ يُسۡتَضۡعَفُونَ مَشَٰرِقَ ٱلۡأَرۡضِ وَمَغَٰرِبَهَا ٱلَّتِي بَٰرَكۡنَا فِيهَاۖ﴾. ابن تيمية:٣/١٩٤.\nهذه الآية الكريمة دليل على بركة أرض الشام، بين ذلك.\nوَتَمَّتۡ كَلِمَتُ رَبِّكَ ٱلۡحُسۡنَىٰ عَلَىٰ بَنِيٓ إِسۡرَٰٓءِيلَ بِمَا صَبَرُواْۖ\nيعني: بتمامها نفاذ ما وعدهم به من النصر على فرعون وإهلاكه. ابن تيمية:٣/١٩٤.\nما معنى تمام كلمة الله تعالى المذكور في الآية الكريمة؟"],[167,"§الأعراف\nwords\nوَجَاوَزنَاعَبَرنَا.\nيَعكُفُونَيُقِيمُونَ عَابِدِينَ.\nإِلَهًاصَنَمًا.\nمُتَبَّرٌمُهلَكٌ.\nيَسُومُونَكُميُذِيقُونَكُم، وَيُكَلِّفُونَكُم.\nلِمِيقَاتِنَافِي الوَقتِ الَّذِي وَاعَدنَاهُ فِيهِ.\nصَعِقًامَغشِيًّا عَلَيهِ.\ndeeds\nألق درسًا، أو أرسل رسالةً عن خطر الشرك بالله، وأثره في بطلان العمل.\nاستخدم وسيلة حكيمة في تعليم من يقع في نوع من الشرك، ووجِّهْهُ للحق.\nقل: \"سبحان الله وبحمده، سبحان الله العظيم\" مائة مرة.\nguid\nأشد الجهل: الجهل بالتوحيد.\nالمحافظة على المواعيد أمر محبوب للشارع، مرغب فيه، وهو من سمات الصادقين.\nالإصلاح من سبل الأنبياء، فكن على نهج الأنبياء، ولا تتبع سبيل المفسدين.\nrefl\nوَجَٰوَزۡنَا بِبَنِيٓ إِسۡرَٰٓءِيلَ ٱلۡبَحۡرَ فَأَتَوۡاْ عَلَىٰ قَوۡمٖ يَعۡكُفُونَ عَلَىٰٓ أَصۡنَامٖ لَّهُمۡۚ قَالُواْ يَٰمُوسَى ٱجۡعَل لَّنَآ إِلَٰهٗا كَمَا لَهُمۡ ءَالِهَةٞۚ قَالَ إِنَّكُمۡ قَوۡمٞ تَجۡهَلُونَ ١٣٨\n﴿إِنَّكُمۡ قَوۡمٌ تَجۡهَلُونَ﴾: وأي جهل أعظم مِن جَهْل مَن جهِلَ ربه وخالقه، وأراد أن يسوِّي به غيره ممن لا يملك نفعًا ولا ضرًّا، ولا موتًا ولا حياةً ولا نشورًا؟! السعدي:٣٠٢.\nما أعظم الجهل؟ ولماذا؟\nقَالُواْ يَٰمُوسَى ٱجۡعَل لَّنَآ إِلَٰهٗا كَمَا لَهُمۡ ءَالِهَةٞۚ قَالَ إِنَّكُمۡ قَوۡمٞ تَجۡهَلُونَ ١٣٨\nوكان وصف موسى إياهم بالجهالة مؤكَّدًا؛ لما دلت عليه الجملة الاسمية من كون الجهالة صفة ثابتة فيهم، وراسخة من نفوسهم، ولولا ذلك لكان لهم في بادي النظر زاجر عن مثل هذا السؤال. ابن عاشور:٩/٨٢.\nكيف دلت الآية الكريمة على أن الجهل قد يوصل إلى الشرك؟\nقَالَ أَغَيۡرَ ٱللَّهِ أَبۡغِيكُمۡ إِلَٰهٗا وَهُوَ فَضَّلَكُمۡ عَلَى ٱلۡعَٰلَمِينَ ١٤٠\nوالمراد بالعالمين: أمم عصرهم. وتفضيلهم عليهم بأنهم ذرية رسول وأنبياء، وبأن منهم رسلًا وأنبياء، وبأن الله هداهم إلى التوحيد والخلاص من دين فرعون بعد أن تخبطوا فيه، وبأنه جعلهم أحرارًا بعد أن كانوا عبيدًا، وساقهم إلى امتلاك أرض مباركة، وأيدهم بنصره وآياته، وبعث فيهم رسولًا ليقيم لهم الشريعة، وهذه الفضائل لم تجتمع لأمة غيرهم يومئذ. ابن عاشور:٩/٨٤.\nما المراد بالعالمين في الآية الكريمة؟ وبما فضل الله تعالى بني إسرائيل على العالمين؟\nوَقَالَ مُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخۡلُفۡنِي فِي قَوۡمِي وَأَصۡلِحۡ وَلَا تَتَّبِعۡ سَبِيلَ ٱلۡمُفۡسِدِينَ ١٤٢\nولما ذهب موسى إلى ميقات ربه قال لهارون موصيًا له على بني إسرائيل من حرصه عليهم وشفقته: ﴿ٱخۡلُفۡنِي فِي قَوۡمِي﴾ أي: كن خليفتي فيهم، واعمل فيهم بما كنت أعمل، (وأصلح) أي: اتبع طريق الصلاح، ﴿وَلَا تَتَّبِعۡ سَبِيلَ ٱلۡمُفۡسِدِينَ﴾: وهم الذين يعملون بالمعاصي. السعدي:٣٠٢.\nالأنبياء أكثر الناس شفقة وحرصًا على أقوامهم، وضِّح ذلك من خلال الآية.\nوَقَالَ مُوسَىٰ لِأَخِيهِ هَٰرُونَ ٱخۡلُفۡنِي فِي قَوۡمِي وَأَصۡلِحۡ وَلَا تَتَّبِعۡ سَبِيلَ ٱلۡمُفۡسِدِينَ ١٤٢\nاستخلف موسى على بني إسرائيل أخاه هارون، ووصَّاه بالإصلاح وعدم الإفساد، هذا تنبيه وتذكير، وإلا فهارون -عليه السلام- نبي شريف كريم على الله، له وجاهة وجلالة. ابن كثير:٢/٢٣٤.\nكل الصالحين بحاجة إلى التذكير حتى الأنبياء -عليهم السلام-، وضح ذلك.\nوَلَٰكِنِ ٱنظُرۡ إِلَى ٱلۡجَبَلِ فَإِنِ ٱسۡتَقَرَّ مَكَانَهُۥ فَسَوۡفَ تَرَىٰنِيۚ فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلۡجَبَلِ جَعَلَهُۥ دَكّٗا وَخَرَّ مُوسَىٰ صَعِقٗاۚ\nفإنه أكبر منك، وأشد خلقًا، ﴿فَلَمَّا تَجَلَّىٰ رَبُّهُۥ لِلۡجَبَلِ﴾ فنظر إلى الجبل لا يتمالك، وأقبل الجبل فدُكَّ على أوله، ورأى موسى ما يصنع الجبل؛ فخرّ صعقًا. ابن كثير:٢/٢٣٥.\nبينت الآية شيئًا من عظمة الله، وضح ذلك.\nفَلَمَّآ أَفَاقَ قَالَ سُبۡحَٰنَكَ تُبۡتُ إِلَيۡكَ وَأَنَا۠ أَوَّلُ ٱلۡمُؤۡمِنِينَ ١٤٣\nقيل: قال على جهة الإنابة إلى الله والخشوع له عند ظهور الآيات، وأجمعت الأمة على أن هذه التوبة ما كانت عن معصية؛ فإن الأنبياء معصومون. القرطبي:١٠/٤٣٩.\nهل الاستغفار لا يكون إلا من معصية؟"],[168,"§الأعراف\nwords\nالأَلوَاحِأَلوَاحِ التَّورَاةِ.\nحَبِطَتبَطَلَت.\nحُلِيِّهِمذَهَبِهِم.\nخُوَارٌصَوتٌ يُسمَعُ؛ كَصَوتِ البَقَرِ.\nسُقِطَ فِي أَيدِيهِمنَدِمُوا.\ndeeds\nاتبع اليوم وسيلة جديدة تزيد من جديتك في أخذ كتاب الله؛ مثل العزم على العمل بما قرأت، وشكر الله على تحبيب كتاب الله لك.\nتذكر خمسًا من نعم الله عليك، ثم اشكر الله تعالى عليها.\nاستعذ بالله تعالى أن يصرف قلبك عن ذكره وفهم كتابه.\nguid\nمن أقوى عوامل الصرف عن فهم آيات الله: الكبر.\nتقبيح الغباء، والجمود، وعدم تفكر الإنسان في حاله وواقعه، وما حوله.\nإذا أراد الله بعبده خيرًا ألهمه التوبة بعد المعصية؛ فندم واستغفر.\nrefl\nقَالَ يَٰمُوسَىٰٓ إِنِّي ٱصۡطَفَيۡتُكَ عَلَى ٱلنَّاسِ\nيذكر تعالى أنه خاطب موسى بأنه اصطفاه على عالمي زمانه برسالاته وكلامه، ولا شك أن محمدًا -صلى الله عليه وسلم- سيد ولد آدم من الأولين والآخرين، ولهذا اختصه الله بأن جعله خاتم الأنبياء والمرسلين؛ الذي تستمر شريعته إلى قيام الساعة، وأتباعه أكثر من أتباع الأنبياء كلهم. ابن كثير:٢/٢٣٦.\nهل تدل الآية على تفضيل موسى على نبينا -عليهما الصلاة والسلام-؟\nقَالَ يَٰمُوسَىٰٓ إِنِّي ٱصۡطَفَيۡتُكَ عَلَى ٱلنَّاسِ بِرِسَٰلَٰتِي وَبِكَلَٰمِي\nفلما منعه الله من رؤيته بعد ما كان متشوقًا إليها أعطاه خيرًا كثيرًا. السعدي:٣٠٢.\nإذا حَرَم الله الصادقَ خيرًا عوضه بخير آخر، كيف تستنبط هذه القاعدة من هذه الآية؟\nفَخُذۡهَا بِقُوَّةٖ وَأۡمُرۡ قَوۡمَكَ يَأۡخُذُواْ بِأَحۡسَنِهَاۚ سَأُوْرِيكُمۡ دَارَ ٱلۡفَٰسِقِينَ ١٤٥\n﴿فَخُذۡهَا بِقُوَّةٍ﴾ أي: بجد واجتهاد، وقيل: بقوة القلب، وصحة العزيمة؛ لأنه إذا أخذه بضعف النية أداه إلى الفتور. البغوي:٢/١٥٢.\nبماذا أُمرنا في أخذ الوحي وتلقيه؟\nفَخُذۡهَا بِقُوَّةٖ وَأۡمُرۡ قَوۡمَكَ يَأۡخُذُواْ بِأَحۡسَنِهَاۚ سَأُوْرِيكُمۡ دَارَ ٱلۡفَٰسِقِينَ ١٤٥\nفدل على أن فيما أُنزل حسن وأحسن. ابن تيمية:٣/١٩٨.\nالتقرب إلى الله سبحانه باتباع الوحي على درجات، وضح ذلك من الآية.\nسَأَصۡرِفُ عَنۡ ءَايَٰتِيَ ٱلَّذِينَ يَتَكَبَّرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ وَإِن يَرَوۡاْ كُلَّ ءَايَةٖ لَّا يُؤۡمِنُواْ بِهَا وَإِن يَرَوۡاْ سَبِيلَ ٱلرُّشۡدِ لَا يَتَّخِذُوهُ سَبِيلٗا وَإِن يَرَوۡاْ سَبِيلَ ٱلۡغَيِّ يَتَّخِذُوهُ سَبِيلٗاۚ\nقال ابن عباس: \"يريد: الذين يتجبرون على عبادي، ويحاربون أوليائي حتى لا يؤمنوا بي\"؛ يعني: سأصرفهم عن قبول آياتي، والتصديق بها؛ عوقبوا بحرمان الهداية لعنادهم للحق؛ كقوله: ﴿فَلَمَّا زَاغُوٓاْ أَزَاغَ ٱللَّهُ قُلُوبَهُمۡ﴾ [الصف: ٥]. البغوي:٢/١٥٢.\nما أشد عقوبات المتكبرين؟\nسَأَصۡرِفُ عَنۡ ءَايَٰتِيَ ٱلَّذِينَ يَتَكَبَّرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ\nقال بعض السلف: \"لا ينال العلم حيي ولا مستكبر\"، وقال آخر: \"من لم يصبر على ذُلِّ التعلم ساعة بقي في ذُلِّ الجهل أبدًا\". ابن كثير:٢/٢٣٧.\nفي هذه الآية بعض الآداب المتعلقة بطالب العلم، اذكر شيئًا منها.\nسَأَصۡرِفُ عَنۡ ءَايَٰتِيَ ٱلَّذِينَ يَتَكَبَّرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ\nإذا كان المصحفُ الذي كُتِب فيه طاهرًا لا يمسُّه إلاّ البدن الطاهر؛ فالمعاني التي هي باطنُ القرآن لا يمسُّها إلاّ القلوبُ المطهرة، وأمَّا القلوب المنجسة لا تمسُّ حقائقَه، فهذا معنىً صحيح؛ قال تعالى: ﴿سَأَصۡرِفُ عَنۡ ءَايَٰتِيَ ٱلَّذِينَ يَتَكَبَّرُونَ فِي ٱلۡأَرۡضِ بِغَيۡرِ ٱلۡحَقِّ﴾. قال بعض السلف: \"أَمنَعُ قلوبَهم فهمَ القرآن\". ابن تيمية:٣/١٩٨.\nمن خطورة التكبر أنه يؤدي إلى عدم فهم القرآن الكريم، بين ذلك."],[169,"§الأعراف\nwords\nأَسِفًاحَزِينًا.\nسَكَتَسَكَنَ.\nلِمِيقَاتِنَالِلوَقتِ وَالأَجَلِ الَّذِي وَاعَدنَاهُ فِيهِ.\nالرَّجفَةُالزَّلزَلَةُ الشَّدِيدَةُ.\ndeeds\nإن تعرضت هذا اليوم لموقف يغضبك فتوضأ، واجلس إن كنت قائمًا، واستعذ بالله تعالى من الشيطان الرجيم.\nاستغفر الله تعالى وتب إليه مما اقترفت من الأخطاء والسيئات.\nادع وتضرع إليه أن لا يؤاخذنا بما فعل السفهاء منا.\nguid\nللأخ أن يعاتب أخاه المسلم، ولكن بعيدًا عن سمع المتربصين بالإسلام، وشماتتهم.\nصاحب البدعة والشرك تغشاه الذلة، ولو تظاهر بالعزة بجاهه أو ماله.\nترك الأمر بالمعروف والنهي عن المنكر موجب لدمار المجتمع وخرابه.\nrefl\nوَلَمَّا رَجَعَ مُوسَىٰٓ إِلَىٰ قَوۡمِهِۦ غَضۡبَٰنَ أَسِفٗا قَالَ بِئۡسَمَا خَلَفۡتُمُونِي مِنۢ بَعۡدِيٓۖ\nلتمام غيرته -عليه الصلاة والسلام-، وكمال نصحه وشفقته. السعدي:٣٠٣.\nما سبب غضب موسى وأسفه -عليه السلام-؟\nأَعَجِلۡتُمۡ أَمۡرَ رَبِّكُمۡۖ\nوالعجلة: التقدم بالشيء قبل وقته؛ وهي مذمومة، والسرعة: عمل الشيء في أول أوقاته؛ وهي محمودة. القرطبي:٩/٣٣٨.\nما الفرق بين العجلة والسرعة؟ وأيهما المحمود؟\nقَالَ ٱبۡنَ أُمَّ إِنَّ ٱلۡقَوۡمَ ٱسۡتَضۡعَفُونِي وَكَادُواْ يَقۡتُلُونَنِي\nوإنَّما قال ﴿ٱبۡنَ أُمَّ﴾ ليكون أَرَقَّ وأنجع عنده؛ وإلا فهو شقيقه لأبيه وأمه. ابن كثير: ٢/٢٣٨.\nالصالحون يختارون أحسن الألفاظ للوصول إلى المقصود، وضح ذلك من الآية.\nإِنَّ ٱلَّذِينَ ٱتَّخَذُواْ ٱلۡعِجۡلَ سَيَنَالُهُمۡ غَضَبٞ مِّن رَّبِّهِمۡ وَذِلَّةٞ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَاۚ وَكَذَٰلِكَ نَجۡزِي ٱلۡمُفۡتَرِينَ ١٥٢\nأعقبهم ذلك ذلًّا وصغارًا في الحياة الدنيا، وقوله: ﴿وَكَذَٰلِكَ نَجۡزِي ٱلۡمُفۡتَرِينَ﴾ نائلة لكل من افترى بدعةً؛ فإن ذل البدعة ومخالفة الرشاد متصلة من قلبه على كتفيه، كما قال الحسن البصري: \"إن ذل البدعة على أكتافهم؛ وإن هملجت بهم البغلات، وطقطقت بهم البراذين\".... وقال سفيان بن عيينة: \"كل صاحب بدعة ذليل\". ابن كثير:٢/٢٣٨.\nما عاقبة الابتداع في الدين؟\nوَلَمَّا سَكَتَ عَن مُّوسَى ٱلۡغَضَبُ أَخَذَ ٱلۡأَلۡوَاحَۖ وَفِي نُسۡخَتِهَا هُدٗى وَرَحۡمَةٞ لِّلَّذِينَ هُمۡ لِرَبِّهِمۡ يَرۡهَبُونَ ١٥٤\nقال سهل بن عبد الله: \"وأصل كل خير في الدنيا والآخرة الخوف من الله\". ويدل على ذلك قوله تعالى: ﴿وَلَمَّا سَكَتَ عَن مُّوسَى ٱلۡغَضَبُ أَخَذَ ٱلۡأَلۡوَاحَۖ وَفِي نُسۡخَتِهَا هُدًى وَرَحۡمَةٌ لِّلَّذِينَ هُمۡ لِرَبِّهِمۡ يَرۡهَبُونَ﴾. ابن تيمية:٣/٢٠٨.\nأصل كل خير في الدنيا والآخرة الخوف من الله تعالى، بيّن ذلك من الآية الكريمة.\nأَتُهۡلِكُنَا بِمَا فَعَلَ ٱلسُّفَهَآءُ مِنَّآۖ\nأي: أتهلكنا وتهلك سائر بني إسرائيل بما فعل السفهاء -الذين طلبوا الرؤية حين قالوا: أرنا الله جهرة، والذين عبدوا العجل-؛ فمعنى هذا إدلاء بحجته، وتبرؤ من فعل السفهاء، ورغبة إلى الله أن لا يعم الجميع بالعقوبة. ابن جزي:١/٣١٨.\nمن أشد المخاطر على المجتمع ترك الأمر بالمعروف والنهي عن المنكر، وضح ذلك من الآية.\nإِنۡ هِيَ إِلَّا فِتۡنَتُكَ تُضِلُّ بِهَا مَن تَشَآءُ وَتَهۡدِي مَن تَشَآءُۖ\nأي: محنتك، واختبارك، وابتلاؤك؛ كما ابتليت عبادك بالحسنات والسيئات ليتبين الصبار الشكور من غيره، وابتليتهم بإرسال الرسل وإنزال الكتب؛ ليتبين المؤمن من الكافر، والصادق من الكاذب، والمنافق من المخلص؛ فتجعل ذلك سببًا لضلالة قوم وهدى آخرين. ابن تيمية:٣/٢٠٨.\nما الحكمة من الابتلاء والامتحان بالحسنات والسيئات؟"]])